Extended worker pool that supports task priorities — high-priority tasks jump the queue ahead of normal ones.

```javascript
class PriorityWorkerPool {
  #workers = [];
  #queues = { high: [], normal: [], low: [] };
  #size;

  constructor(workerScript, size = 4) {
    this.#size = size;
    for (let i = 0; i < size; i++) this.#addWorker(workerScript);
  }

  #addWorker(script) {
    const worker = new Worker(script);
    worker.idle = true;
    worker.onmessage = (e) => {
      worker.pending.resolve(e.data);
      worker.idle = true;
      this.#dispatch();
    };
    worker.onerror = (e) => {
      worker.pending.reject(e);
      worker.idle = true;
      this.#dispatch();
    };
    this.#workers.push(worker);
  }

  #nextTask() {
    for (const priority of ['high', 'normal', 'low']) {
      if (this.#queues[priority].length) return this.#queues[priority].shift();
    }
    return null;
  }

  #dispatch() {
    const task = this.#nextTask();
    if (!task) return;
    const worker = this.#workers.find(w => w.idle);
    if (!worker) return; // will dispatch when worker becomes free

    worker.idle = false;
    worker.pending = task;
    worker.postMessage(task.payload);
  }

  run(payload, priority = 'normal') {
    return new Promise((resolve, reject) => {
      this.#queues[priority].push({ payload, resolve, reject });
      this.#dispatch();
    });
  }
}

const pool = new PriorityWorkerPool('compute.js', 4);

// Low priority background work
pool.run({ type: 'analytics', data: events }, 'low');
// High priority user-facing work — skips ahead
pool.run({ type: 'render', data: frame }, 'high');
```

setTimeout does not guarantee execution at exactly the specified delay — under CPU load, timers fire late. Code assuming precise timing order between multiple timers is fragile.

Bug — assuming timer order:
```javascript
let state = 'initial';

setTimeout(() => {
  state = 'first'; // should run first
}, 0);

setTimeout(() => {
  console.log(state); // assumes 'first' — but may still be 'initial' under load!
}, 0);
```

Bug — timer-based synchronization:
```javascript
async function initModule() {
  initPartA();
  setTimeout(() => initPartB(), 100); // assume partA done in 100ms — fragile!
}

async function useModule() {
  setTimeout(() => {
    // Assumes module initialized — 100ms should be enough... right?
    callModuleMethod(); // may throw if partB not done yet
  }, 150);
}
```

Fix — use promises for ordering, not timers:
```javascript
const initPromise = initPartA().then(() => initPartB());

async function useModule() {
  await initPromise; // deterministic — no timing assumption
  callModuleMethod();
}
```

Fix — event/signal based:
```javascript
const ready = Promise.withResolvers();

function initModule() {
  initPartA();
  initPartB();
  ready.resolve(); // signal completion
}

async function useModule() {
  await ready.promise; // wait for signal — not a timer
  callModuleMethod();
}
```

