Semaphore limits concurrent access to N slots. When N slots are taken, new acquirers wait until one is released. Essential for connection pools, API rate limits, and throttled operations.

Full Semaphore implementation:
```javascript
class Semaphore {
  #count;
  #queue = [];

  constructor(count) {
    this.#count = count;
  }

  async acquire() {
    if (this.#count > 0) {
      this.#count--;
      return;
    }
    await new Promise(resolve => this.#queue.push(resolve));
    this.#count--;
  }

  release() {
    this.#count++;
    if (this.#queue.length && this.#count > 0) {
      this.#queue.shift()();
    }
  }

  async run(fn) {
    await this.acquire();
    try {
      return await fn();
    } finally {
      this.release();
    }
  }
}

// Max 3 concurrent API calls
const sem = new Semaphore(3);
const results = await Promise.all(
  Array.from({ length: 20 }, (_, i) =>
    sem.run(() => fetch(`/api/item/${i}`).then(r => r.json()))
  )
);
// Only 3 fetch calls run at a time — 20 total, batched in groups of 3
```

Database connection pool:
```javascript
class ConnectionPool {
  #sem;
  #connections;

  constructor(maxConnections) {
    this.#sem = new Semaphore(maxConnections);
    this.#connections = [];
  }

  async withConnection(fn) {
    await this.#sem.acquire();
    const conn = await this.#getOrCreate();
    try {
      return await fn(conn);
    } finally {
      this.#connections.push(conn); // return to pool
      this.#sem.release();
    }
  }

  async #getOrCreate() {
    return this.#connections.pop() ?? await createConnection();
  }
}

const pool = new ConnectionPool(5);
await pool.withConnection(conn => conn.query('SELECT * FROM users'));
```

In async middleware pipelines (Express, Koa), if a middleware calls next() but also does async work after it, that work races with downstream middleware.

Bug — async work after next():
```javascript
// Express middleware
app.use(async (req, res, next) => {
  const start = Date.now();
  await next(); // downstream runs
  // Code after next() runs after response is sent — may be too late!
  const duration = Date.now() - start;
  await logToDB({ path: req.path, duration }); // may fail — response already sent
});

// Worse — modifying response after next():
app.use(async (req, res, next) => {
  await next();
  res.setHeader('X-Duration', Date.now()); // ERROR: headers already sent!
});
```

Fix — complete side effects before calling next(), or use Koa-style:
```javascript
// Koa style — works correctly because next() is awaited:
app.use(async (ctx, next) => {
  const start = Date.now();
  await next(); // WAIT for downstream to complete
  const duration = Date.now() - start; // runs after full downstream chain
  ctx.set('X-Duration', duration); // safe — response not sent yet in Koa
});
```

Fix — Express: use res.on('finish') for post-response logging:
```javascript
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => { // fires after response sent
    const duration = Date.now() - start;
    logToDB({ path: req.path, duration }).catch(console.error);
  });
  next();
});
```

Fix — never mutate request/response after calling next():
```javascript
app.use(async (req, res, next) => {
  req.startTime = Date.now(); // set BEFORE next
  next(); // not awaited — fire and continue
});

app.use((req, res) => {
  res.json({ data, duration: Date.now() - req.startTime });
});
```

Execute async tasks in dependency order — tasks with no dependencies run first (in parallel), then tasks whose dependencies are satisfied, and so on. Topological sort for async work.

```javascript
class AsyncTaskGraph {
  #tasks = new Map();

  add(name, deps, fn) {
    this.#tasks.set(name, { deps, fn });
    return this;
  }

  async run() {
    const results = new Map();
    const executing = new Map(); // name -> promise

    const runTask = (name) => {
      if (executing.has(name)) return executing.get(name);

      const { deps, fn } = this.#tasks.get(name);

      const promise = Promise.all(deps.map(dep => runTask(dep)))
        .then(depResults => {
          const depMap = Object.fromEntries(deps.map((d, i) => [d, depResults[i]]));
          return fn(depMap);
        })
        .then(result => {
          results.set(name, result);
          return result;
        });

      executing.set(name, promise);
      return promise;
    };

    await Promise.all([...this.#tasks.keys()].map(runTask));
    return results;
  }
}

// Build pipeline: fetch → parse → transform → save (with parallelism)
const graph = new AsyncTaskGraph()
  .add('fetchUsers', [], () => fetch('/api/users').then(r => r.json()))
  .add('fetchRoles', [], () => fetch('/api/roles').then(r => r.json()))
  .add('merge', ['fetchUsers', 'fetchRoles'], ({ fetchUsers, fetchRoles }) =>
    mergeUsersAndRoles(fetchUsers, fetchRoles))
  .add('validate', ['merge'], ({ merge }) => validateAll(merge))
  .add('save', ['validate'], ({ validate }) => saveToDatabase(validate));

const results = await graph.run();
// fetchUsers and fetchRoles run in parallel
// merge waits for both; validate waits for merge; save waits for validate
```

Returning a promise from an async function without await means the async wrapper's finally/catch doesn't cover the returned promise — resource leaks and missed errors.

Bug — missing await loses error context:
```javascript
async function getUser(id) {
  try {
    return fetchUser(id); // NOT awaited — returns promise
    // If fetchUser rejects, this try/catch DOES NOT catch it!
  } catch (err) {
    logError(err); // never runs
    throw err;
  }
}

// Caller still gets a rejected promise, but error is NOT logged
await getUser(999); // rejects, but logger missed it
```

Bug — resource leak without await:
```javascript
async function processWithResource() {
  const resource = await acquireResource();
  try {
    return doWork(resource); // NOT awaited — returns promise
    // If doWork rejects, finally runs BEFORE the work is done!
  } finally {
    await resource.release(); // releases BEFORE doWork settles!
  }
}
```

Fix — always await when in try/finally or try/catch:
```javascript
async function getUser(id) {
  try {
    return await fetchUser(id); // await — error caught here
  } catch (err) {
    logError(err); // now runs on rejection
    throw err;
  }
}

async function processWithResource() {
  const resource = await acquireResource();
  try {
    return await doWork(resource); // await — finally runs after work settles
  } finally {
    await resource.release(); // runs after doWork completes or rejects
  }
}
```

When return-without-await is OK:
```javascript
// OK — no try/catch/finally wrapping the return
async function simpleWrapper(id) {
  const validated = validateId(id);
  return fetchUser(validated); // fine — no error handling needed here
}
```

Rule: inside try/catch or try/finally blocks, always await before returning.

When events must be processed in strict arrival order (WebSocket messages, SSE events, user actions), a sequential async queue serializes handlers while preserving order.

Order-preserving async queue:
```javascript
class OrderedAsyncQueue {
  #chain = Promise.resolve();
  #size = 0;
  #maxSize;

  constructor(maxSize = Infinity) {
    this.#maxSize = maxSize;
  }

  enqueue(handler) {
    if (this.#size >= this.#maxSize) {
      throw new Error(`Queue full (max ${this.#maxSize})`);
    }
    this.#size++;
    const result = this.#chain.then(async () => {
      try {
        return await handler();
      } finally {
        this.#size--;
      }
    });
    this.#chain = result.catch(() => {}); // don't let errors break the chain
    return result;
  }

  get pending() { return this.#size; }
}

// WebSocket ordered processing
const queue = new OrderedAsyncQueue(100);

ws.onmessage = (event) => {
  const data = JSON.parse(event.data);
  queue.enqueue(async () => {
    const processed = await processMessage(data); // may take varying time
    applyToState(processed); // always applied in arrival order
  }).catch(err => console.error('Handler failed:', err));
};
```

With back-pressure signal:
```javascript
class BackpressureQueue {
  #queue = new OrderedAsyncQueue(50);

  enqueue(handler) {
    if (this.#queue.pending >= 50) {
      return Promise.reject(new Error('429: Queue full'));
    }
    return this.#queue.enqueue(handler);
  }

  get pressure() {
    return this.#queue.pending / 50; // 0-1 saturation
  }
}
```

SharedWorker instances are shared across same-origin tabs. Multiple tabs writing to shared worker state concurrently without coordination creates race conditions.

Bug — concurrent state modification via SharedWorker:
```javascript
// shared-worker.js
let sharedCounter = 0;

self.onconnect = (e) => {
  const port = e.ports[0];
  port.onmessage = (msg) => {
    if (msg.data.type === 'increment') {
      sharedCounter++; // safe — single-threaded worker
      port.postMessage({ counter: sharedCounter });
    }
  };
};
// Counter is safe inside SharedWorker (single thread)
// But coordination across ports needs serialization
```

Bug — concurrent async operations in SharedWorker:
```javascript
self.onconnect = (e) => {
  const port = e.ports[0];
  port.onmessage = async (msg) => {
    const current = sharedData.value; // read
    await fetchUpdate(); // yield — another port's message can run here!
    sharedData.value = current + 1; // write — lost update!
  };
};
```

Fix — queue all messages through serial processor:
```javascript
// shared-worker.js
let sharedState = {};
const ports = new Set();
let processing = Promise.resolve();

function broadcast(data) {
  ports.forEach(p => p.postMessage(data));
}

self.onconnect = (e) => {
  const port = e.ports[0];
  ports.add(port);

  port.onmessage = (msg) => {
    // Serialize all state mutations through a queue
    processing = processing.then(async () => {
      const result = await handleMessage(msg.data, sharedState);
      sharedState = result.newState;
      broadcast(sharedState); // all tabs get updated state
    }).catch(err => console.error('Worker error:', err));
  };

  port.onclose = () => ports.delete(port);
};
```

Poll a resource until a condition is met, with exponential backoff between attempts and configurable timeout. Used for waiting on asynchronous server-side operations.

```javascript
async function pollUntil({
  fn,           // function to poll — returns value or throws
  condition,    // (value) => boolean — stop when true
  signal,       // AbortSignal for cancellation
  initialDelay = 500,
  maxDelay = 30000,
  timeout = 300000, // 5 min total timeout
  maxAttempts = Infinity
}) {
  const deadline = Date.now() + timeout;
  let delay = initialDelay;
  let attempts = 0;

  while (Date.now() < deadline && attempts < maxAttempts) {
    if (signal?.aborted) throw new DOMException('Polling cancelled', 'AbortError');

    try {
      const result = await fn();
      if (condition(result)) return result; // done!
    } catch (err) {
      if (err.name === 'AbortError') throw err;
      // continue polling on error
    }

    attempts++;
    await new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, delay);
      signal?.addEventListener('abort', () => {
        clearTimeout(timer);
        reject(new DOMException('Polling cancelled', 'AbortError'));
      }, { once: true });
    });

    delay = Math.min(delay * 2, maxDelay);
  }

  throw new Error(`Polling timed out after ${attempts} attempts`);
}

// Wait for async job to complete:
const job = await fetch('/api/jobs', { method: 'POST', body: payload }).then(r => r.json());

const result = await pollUntil({
  fn: () => fetch(`/api/jobs/${job.id}`).then(r => r.json()),
  condition: (job) => job.status === 'completed' || job.status === 'failed',
  initialDelay: 1000,
  maxDelay: 10000,
  timeout: 120000,
});

if (result.status === 'failed') throw new Error(result.error);
return result.output;
```

JavaScript object property iteration order is implementation-defined for some cases. Async code that depends on property insertion order may behave differently across engines or after refactoring.

Fragile — assumes insertion order for async coordination:
```javascript
const asyncTasks = {
  fetchUser: fetchUser(),
  fetchOrders: fetchOrders(), // assumed to run in this order
  fetchSettings: fetchSettings(),
};

// Object.entries order is guaranteed in modern JS for string keys
// (insertion order) — but relying on it for async sequencing is fragile
for (const [name, promise] of Object.entries(asyncTasks)) {
  const result = await promise; // sequential — relies on order
  processResult(name, result);
}
```

Fix — explicit array for ordered async operations:
```javascript
const tasks = [
  { name: 'fetchUser', promise: fetchUser() },
  { name: 'fetchOrders', promise: fetchOrders() },
  { name: 'fetchSettings', promise: fetchSettings() },
];

// Order is explicit and guaranteed
const results = await Promise.all(tasks.map(t => t.promise));
const resultMap = Object.fromEntries(tasks.map((t, i) => [t.name, results[i]]));
```

Anti-pattern — object spread loses async result association:
```javascript
// BAD: spread order may not match execution order
const results = await Promise.all(Object.values(asyncTasks));
const keys = Object.keys(asyncTasks);
// keys[i] may not correspond to results[i] if object mutated async
```

Fix — always use Map or array of tuples for ordered key-value async:
```javascript
const taskPairs = [
  ['user', () => fetchUser(id)],
  ['orders', () => fetchOrders(id)],
];

const results = await Promise.all(
  taskPairs.map(([key, fn]) => fn().then(v => [key, v]))
);
const data = new Map(results);
```

Mutex (mutual exclusion lock) allows exactly one async operation at a time. Ownership tracking helps debug deadlocks and double-release bugs.

Full Mutex implementation:
```javascript
class Mutex {
  #locked = false;
  #queue = [];
  #owner = null; // debug: who holds the lock

  async acquire(name = 'anonymous') {
    if (!this.#locked) {
      this.#locked = true;
      this.#owner = name;
      return;
    }
    await new Promise(resolve => this.#queue.push({ resolve, name }));
  }

  release() {
    if (!this.#locked) {
      throw new Error('Mutex released when not locked');
    }
    if (this.#queue.length === 0) {
      this.#locked = false;
      this.#owner = null;
      return;
    }
    const { resolve, name } = this.#queue.shift();
    this.#owner = name;
    resolve();
  }

  async withLock(fn, name) {
    await this.acquire(name);
    try {
      return await fn();
    } finally {
      this.release();
    }
  }

  get isLocked() { return this.#locked; }
  get owner() { return this.#owner; }
}

const mutex = new Mutex();

// Safe concurrent counter:
let counter = 0;
await Promise.all([
  mutex.withLock(async () => { counter++; await delay(10); }, 'task-1'),
  mutex.withLock(async () => { counter++; await delay(10); }, 'task-2'),
  mutex.withLock(async () => { counter++; await delay(10); }, 'task-3'),
]);
console.log(counter); // 3 — correct

// Timeout to detect deadlocks:
async function acquireWithTimeout(mutex, ms, name) {
  const timeout = new Promise((_, rej) =>
    setTimeout(() => rej(new Error(`Deadlock? ${name} waiting ${ms}ms for ${mutex.owner}`)), ms)
  );
  await Promise.race([mutex.acquire(name), timeout]);
}
```

Multiple UI components simultaneously requesting the same data trigger duplicate network requests. Request deduplication coalesces concurrent identical requests into one.

Bug — N components cause N fetches:
```javascript
const UserAvatar = ({ userId }) => {
  const [user, setUser] = useState(null);
  useEffect(() => {
    fetch(`/api/users/${userId}`).then(r => r.json()).then(setUser);
    // 50 UserAvatar components with same userId = 50 fetches!
  }, [userId]);
};
```

Fix — request deduplication cache:
```javascript
const inflightRequests = new Map();

function fetchDeduped(url) {
  if (inflightRequests.has(url)) {
    return inflightRequests.get(url); // join in-flight request
  }

  const promise = fetch(url)
    .then(r => r.json())
    .finally(() => inflightRequests.delete(url)); // cleanup after settle

  inflightRequests.set(url, promise);
  return promise; // all callers share same promise
}

const UserAvatar = ({ userId }) => {
  const [user, setUser] = useState(null);
  useEffect(() => {
    fetchDeduped(`/api/users/${userId}`).then(setUser);
    // 50 components — 1 network request — all get same data
  }, [userId]);
};
```

With TTL cache (dedup + short-term caching):
```javascript
class RequestCache {
  #cache = new Map(); // url -> {promise, timestamp}
  #ttl;

  constructor(ttlMs = 5000) {
    this.#ttl = ttlMs;
  }

  async get(url, fetcher = fetch) {
    const cached = this.#cache.get(url);
    if (cached && Date.now() - cached.timestamp < this.#ttl) {
      return cached.promise; // reuse if fresh or still in-flight
    }

    const promise = fetcher(url).then(r => r.json()).catch(err => {
      this.#cache.delete(url); // don't cache errors
      throw err;
    });

    this.#cache.set(url, { promise, timestamp: Date.now() });
    return promise;
  }
}

const requestCache = new RequestCache(5000);
export const fetchUser = (id) => requestCache.get(`/api/users/${id}`);
```

Resource lifecycle hooks (onCreate, onAcquire, onRelease, onDestroy) enable instrumentation, monitoring, and policy enforcement without modifying resource logic.

```javascript
class InstrumentedPool {
  #resources = [];
  #available = [];
  #hooks;
  #maxSize;

  constructor(factory, maxSize = 10, hooks = {}) {
    this.#factory = factory;
    this.#maxSize = maxSize;
    this.#hooks = {
      onCreate: hooks.onCreate ?? (() => {}),
      onAcquire: hooks.onAcquire ?? (() => {}),
      onRelease: hooks.onRelease ?? (() => {}),
      onDestroy: hooks.onDestroy ?? (() => {}),
    };
  }

  async acquire() {
    let resource;
    if (this.#available.length) {
      resource = this.#available.pop();
    } else if (this.#resources.length < this.#maxSize) {
      resource = await this.#factory();
      this.#resources.push(resource);
      await this.#hooks.onCreate(resource);
    } else {
      throw new Error('Pool exhausted');
    }
    await this.#hooks.onAcquire(resource);
    return resource;
  }

  async release(resource) {
    await this.#hooks.onRelease(resource);
    this.#available.push(resource);
  }

  async with(fn) {
    const resource = await this.acquire();
    try { return await fn(resource); }
    finally { await this.release(resource); }
  }
}

// Pool with full observability:
const dbPool = new InstrumentedPool(
  createConnection,
  5,
  {
    onCreate: (conn) => metrics.increment('pool.created'),
    onAcquire: (conn) => {
      conn._acquiredAt = Date.now();
      metrics.gauge('pool.active', 1);
    },
    onRelease: (conn) => {
      const held = Date.now() - conn._acquiredAt;
      metrics.histogram('pool.holdTime', held);
      metrics.gauge('pool.active', -1);
    },
  }
);

await dbPool.with(conn => conn.query('SELECT 1'));
```

Retry logic that catches all errors and retries — including AbortError — will continue retrying even after cancellation is requested. The cancel signal is ignored.

Bad — retries even after abort:
```javascript
async function fetchWithRetry(url, retries = 3) {
  for (let i = 0; i <= retries; i++) {
    try {
      return await fetch(url);
    } catch (err) {
      if (i === retries) throw err;
      await delay(1000 * 2 ** i);
      // AbortError is caught and retried — cancel is swallowed!
    }
  }
}

const ctrl = new AbortController();
const p = fetchWithRetry('/api/data', ctrl.signal);
ctrl.abort(); // IGNORED — fetch retries 3 more times!
await p;
```

Fix — always re-throw AbortError:
```javascript
async function fetchWithRetry(url, signal, retries = 3) {
  for (let i = 0; i <= retries; i++) {
    try {
      return await fetch(url, { signal }); // pass signal
    } catch (err) {
      if (err.name === 'AbortError') throw err; // NEVER retry cancellation
      if (i === retries) throw err;
      // Also check before delay:
      if (signal?.aborted) throw new DOMException('Cancelled', 'AbortError');
      await delay(1000 * 2 ** i, signal); // cancellable delay too
    }
  }
}

// Usage:
const ctrl = new AbortController();
const p = fetchWithRetry('/api/data', ctrl.signal);
ctrl.abort(); // now actually cancels
```

General rule — never retry these:
```javascript
const NEVER_RETRY = new Set(['AbortError', 'TypeError']); // TypeError = network error on bad URL

async function smartRetry(fn, signal, maxRetries = 3) {
  for (let i = 0; i <= maxRetries; i++) {
    try {
      return await fn(signal);
    } catch (err) {
      if (NEVER_RETRY.has(err.name)) throw err; // propagate immediately
      if (i === maxRetries) throw err;
      await delay(500 * 2 ** i, signal);
    }
  }
}
```

Event sourcing stores state changes as immutable events. Projections rebuild state by replaying events asynchronously — enables multiple views of the same data.

```javascript
class EventStore {
  #events = [];
  #subscribers = [];

  async append(event) {
    const entry = {
      id: crypto.randomUUID(),
      type: event.type,
      payload: event.payload,
      timestamp: Date.now(),
    };
    this.#events.push(entry);
    // Notify all projections
    await Promise.all(this.#subscribers.map(sub => sub(entry)));
    return entry;
  }

  subscribe(handler) {
    this.#subscribers.push(handler);
    return () => this.#subscribers.splice(this.#subscribers.indexOf(handler), 1);
  }

  async replay(fromId = null, handler) {
    const start = fromId
      ? this.#events.findIndex(e => e.id === fromId) + 1
      : 0;
    for (const event of this.#events.slice(start)) {
      await handler(event);
    }
  }
}

// Projection: build user count view
class UserCountProjection {
  #count = 0;
  #lastProcessed = null;

  async handle(event) {
    if (event.type === 'USER_CREATED') this.#count++;
    if (event.type === 'USER_DELETED') this.#count--;
    this.#lastProcessed = event.id;
  }

  async rebuild(store) {
    this.#count = 0;
    await store.replay(null, e => this.handle(e));
  }

  get count() { return this.#count; }
}

const store = new EventStore();
const userCount = new UserCountProjection();
store.subscribe(e => userCount.handle(e));

await store.append({ type: 'USER_CREATED', payload: { id: '1' } });
await store.append({ type: 'USER_CREATED', payload: { id: '2' } });
await store.append({ type: 'USER_DELETED', payload: { id: '1' } });
console.log(userCount.count); // 1
```

When session token validation is async (DB lookup, JWT decode), concurrent requests may proceed past validation while a logout/revoke is processed.

Bug — revoke races with validation:
```javascript
const activeSessions = new Set();

async function validateSession(token) {
  // Step 1: check in-memory set (fast)
  if (!activeSessions.has(token)) return false;

  // Step 2: verify signature (slow)
  const payload = await verifyJWT(token); // yield here!
  // While awaiting, logout() may have removed token from activeSessions
  // But this validation still returns true — token accepted after revoke!

  return payload;
}

async function logout(token) {
  activeSessions.delete(token); // runs while validateSession is awaiting verifyJWT
}
```

Fix — re-check after async operation:
```javascript
async function validateSession(token) {
  if (!activeSessions.has(token)) return false;

  const payload = await verifyJWT(token);

  // Re-check after await — token may have been revoked during verification
  if (!activeSessions.has(token)) return false;

  return payload;
}
```

Fix — version-based session invalidation:
```javascript
const sessions = new Map(); // token -> { version, userId }

async function validateSession(token) {
  const session = sessions.get(token);
  if (!session) return false;
  const snapshotVersion = session.version;

  const payload = await verifyJWT(token);

  const current = sessions.get(token);
  if (!current || current.version !== snapshotVersion) return false; // revoked
  return payload;
}

async function logout(token) {
  sessions.delete(token); // or: sessions.get(token).version++ to invalidate
}
```

Fix — centralized auth service with read-your-writes:
```javascript
async function validateSession(token) {
  // Single authoritative check — no split state
  return authService.validate(token); // handles revocation internally
}
```

Multi-stage data processing pipeline where each stage is async, errors in one stage don't crash others, and failed items are tracked separately.

```javascript
class AsyncPipeline {
  #stages = [];

  pipe(name, fn, { optional = false } = {}) {
    this.#stages.push({ name, fn, optional });
    return this;
  }

  async process(items) {
    const succeeded = [];
    const failed = [];

    for (const item of items) {
      let current = item;
      let itemFailed = false;

      for (const { name, fn, optional } of this.#stages) {
        try {
          current = await fn(current);
        } catch (err) {
          if (optional) {
            console.warn(`Optional stage '${name}' failed for item:`, err.message);
            // continue with unmodified current
          } else {
            failed.push({ item, stage: name, error: err });
            itemFailed = true;
            break;
          }
        }
      }

      if (!itemFailed) succeeded.push(current);
    }

    return { succeeded, failed };
  }
}

// Data ingestion pipeline
const pipeline = new AsyncPipeline()
  .pipe('validate', async (row) => {
    if (!row.email) throw new Error('Missing email');
    return row;
  })
  .pipe('enrich', async (row) => ({
    ...row,
    country: await geoLookup(row.ip),
  }), { optional: true }) // enrichment failure doesn't skip the row
  .pipe('normalize', async (row) => ({
    ...row,
    email: row.email.toLowerCase().trim(),
  }))
  .pipe('save', async (row) => {
    await db.upsert('users', row);
    return row;
  });

const { succeeded, failed } = await pipeline.process(importedRows);
console.log(`Processed: ${succeeded.length}, Failed: ${failed.length}`);
failed.forEach(f => console.error(`Row failed at '${f.stage}':`, f.error.message));
```

Two-phase init: eager phase starts expensive async work immediately; lazy phase blocks callers until init completes on first use. Minimizes startup latency.

```javascript
class TwoPhaseService {
  // Phase 1: start immediately (don't await)
  #configPromise = loadConfig();
  #schemaPromise = loadSchema();

  // Phase 2: lazy — completes on first use
  #fullInitPromise = null;

  async #fullInit() {
    const [config, schema] = await Promise.all([
      this.#configPromise,
      this.#schemaPromise,
    ]);
    this.config = config;
    this.schema = schema;
    this.db = await connectDatabase(config.dbUrl);
    this.validator = compileSchema(schema);
  }

  async ready() {
    if (!this.#fullInitPromise) {
      this.#fullInitPromise = this.#fullInit().catch(err => {
        this.#fullInitPromise = null; // allow retry
        throw err;
      });
    }
    return this.#fullInitPromise;
  }

  async processRequest(data) {
    await this.ready(); // blocks until init done — first call only
    if (!this.validator.validate(data)) throw new Error('Invalid input');
    return this.db.execute(this.config.query, data);
  }
}

const service = new TwoPhaseService();
// Config and schema fetch START immediately (phase 1)
// ...
// First actual request triggers phase 2 (db connect + compile)
const result = await service.processRequest(data);
// Subsequent requests — ready() resolves instantly (already settled promise)
```

Benefit over lazy-only init: phase 1 pre-fetches config/schema in parallel with app startup, so phase 2 (db connect) doesn't have to wait for them — total init time is max(phase1, phase2) rather than sum.

Autocomplete fires a request on each keystroke. Without cancellation, older requests that arrive late overwrite newer, more relevant results.

Bug — stale results overwrite current:
```javascript
const searchInput = document.getElementById('search');

searchInput.addEventListener('input', async (e) => {
  const query = e.target.value;
  const results = await fetchSuggestions(query); // slow — 500ms
  displayResults(results); // may display results for old query!
  // User typed 'cat' -> fetch started
  // User typed 'cats' -> fetch started
  // 'cats' fetch resolves first -> displays 'cats' results
  // 'cat' fetch resolves later -> OVERWRITES with stale 'cat' results
});
```

Fix — cancel previous request on new input:
```javascript
let currentController = null;

searchInput.addEventListener('input', async (e) => {
  const query = e.target.value;

  // Cancel previous in-flight request
  currentController?.abort();
  currentController = new AbortController();

  try {
    const results = await fetchSuggestions(query, currentController.signal);
    displayResults(results);
  } catch (err) {
    if (err.name !== 'AbortError') console.error(err);
    // AbortError — this request was superseded, ignore silently
  }
});
```

With debounce to reduce request frequency:
```javascript
let currentController = null;
let debounceTimer = null;

searchInput.addEventListener('input', (e) => {
  const query = e.target.value;

  clearTimeout(debounceTimer);
  currentController?.abort();
  currentController = new AbortController();
  const signal = currentController.signal;

  debounceTimer = setTimeout(async () => {
    try {
      const results = await fetchSuggestions(query, signal);
      displayResults(results);
    } catch (err) {
      if (err.name !== 'AbortError') console.error(err);
    }
  }, 300);
});
```

BroadcastChannel enables same-origin tabs to synchronize state changes — when one tab modifies data, others receive the update immediately without polling.

```javascript
class TabSyncStore {
  #channel;
  #state;
  #subscribers = [];

  constructor(name, initialState) {
    this.#state = initialState;
    this.#channel = new BroadcastChannel(name);

    this.#channel.onmessage = (event) => {
      if (event.data.type === 'STATE_UPDATE') {
        this.#state = event.data.state;
        this.#subscribers.forEach(fn => fn(this.#state));
      }
    };
  }

  async update(updater) {
    this.#state = typeof updater === 'function' ? updater(this.#state) : updater;

    // Broadcast to all other tabs
    this.#channel.postMessage({
      type: 'STATE_UPDATE',
      state: this.#state,
    });

    // Notify local subscribers too
    this.#subscribers.forEach(fn => fn(this.#state));
    return this.#state;
  }

  subscribe(fn) {
    this.#subscribers.push(fn);
    return () => this.#subscribers.splice(this.#subscribers.indexOf(fn), 1);
  }

  get state() { return this.#state; }

  close() { this.#channel.close(); }
}

// Shopping cart shared across tabs:
const cart = new TabSyncStore('shopping-cart', { items: [], total: 0 });

// Tab 1 adds item:
await cart.update(state => ({
  items: [...state.items, newItem],
  total: state.total + newItem.price,
}));
// All other open tabs immediately receive updated cart

cart.subscribe((state) => renderCart(state));
```

Note: BroadcastChannel messages only reach OTHER tabs — the sending tab does NOT receive its own messages. Handle local state update separately (as shown above).

Functions that sometimes return synchronously and sometimes return a Promise cause unpredictable behavior — callers can't reliably use await or .then().

Bad — Zalgo (unpredictable sync vs async):
```javascript
function getData(key) {
  if (cache.has(key)) {
    return cache.get(key); // SYNC return — raw value!
  }
  return fetch(`/api/${key}`).then(r => r.json()); // ASYNC return — Promise!
}

// Caller has no idea which they'll get:
const result = getData('user'); // string or Promise?
if (result.then) { // have to check...
  result.then(process);
} else {
  process(result);
}
```

Fix — always async (always returns Promise):
```javascript
async function getData(key) {
  if (cache.has(key)) {
    return cache.get(key); // async function wraps in Promise.resolve
  }
  const data = await fetch(`/api/${key}`).then(r => r.json());
  cache.set(key, data);
  return data;
}

// Caller always uses await — consistent:
const result = await getData('user');
```

Fix — explicit Promise.resolve for sync paths:
```javascript
function getData(key) {
  if (cache.has(key)) {
    return Promise.resolve(cache.get(key)); // always returns Promise
  }
  return fetch(`/api/${key}`).then(r => {
    const data = r.json();
    cache.set(key, data);
    return data;
  });
}
```

Fix — for sync callers that genuinely need sync, separate the API:
```javascript
function getDataSync(key) { return cache.get(key) ?? null; } // may return null
async function getData(key) { /* always async, always populates cache */ }
```

Rule: a function should either always return a value synchronously OR always return a Promise — never both depending on internal conditions.

Combines reactive state (Proxy) with async action dispatch — similar to Vuex/Redux but lightweight. Actions are async, state is observed synchronously.

```javascript
function createStore(initialState, actions) {
  const subscribers = new Set();
  let state = { ...initialState };

  const reactiveState = new Proxy(state, {
    set(target, key, value) {
      target[key] = value;
      subscribers.forEach(fn => fn({ ...target })); // notify all
      return true;
    }
  });

  const dispatch = async (actionName, payload) => {
    const action = actions[actionName];
    if (!action) throw new Error(`Unknown action: ${actionName}`);
    return action(reactiveState, payload, dispatch);
  };

  const subscribe = (fn) => {
    subscribers.add(fn);
    fn({ ...state }); // immediate call with current state
    return () => subscribers.delete(fn);
  };

  const getState = () => ({ ...state });

  return { dispatch, subscribe, getState };
}

// Usage:
const store = createStore(
  { users: [], loading: false, error: null },
  {
    async loadUsers(state, _, dispatch) {
      state.loading = true; // triggers subscriber
      state.error = null;
      try {
        const users = await fetch('/api/users').then(r => r.json());
        state.users = users;
      } catch (err) {
        state.error = err.message;
      } finally {
        state.loading = false;
      }
    },
    addUser(state, user) {
      state.users = [...state.users, user];
    }
  }
);

const unsubscribe = store.subscribe(state => renderUI(state));
await store.dispatch('loadUsers');
store.dispatch('addUser', { id: 99, name: 'New User' });
```

Sync generators run cooperatively — they only yield control explicitly at yield points. But if multiple generator instances share mutable state, interleaved execution via external schedulers causes races.

Bug — scheduler interleaves generators sharing state:
```javascript
let sharedBalance = 100;

function* deductGen(amount) {
  const current = sharedBalance; // read
  yield; // PAUSE — scheduler may run another generator here
  sharedBalance = current - amount; // write — may be stale
  yield `Deducted ${amount}, balance: ${sharedBalance}`;
}

// External scheduler runs both generators interleaved:
const g1 = deductGen(30);
const g2 = deductGen(30);
g1.next(); // g1 reads balance=100
g2.next(); // g2 reads balance=100
g1.next(); // g1 writes balance=70 (100-30)
g2.next(); // g2 writes balance=70 (100-30) — WRONG! should be 40
console.log(sharedBalance); // 70, expected 40
```

Fix — complete atomic operations before yielding:
```javascript
function* safeDeductGen(amount) {
  // Modify THEN yield — no shared state read after yield point
  if (sharedBalance < amount) {
    yield { ok: false, reason: 'Insufficient funds' };
    return;
  }
  sharedBalance -= amount; // atomic — no yield between read and write
  yield { ok: true, balance: sharedBalance };
}
```

Fix — pass state through generator (no shared mutable):
```javascript
function* pureDeductGen(balance, amount) {
  // No shared state — takes balance as input, yields new balance
  if (balance < amount) {
    yield { ok: false, balance };
    return;
  }
  yield { ok: true, balance: balance - amount };
}

// Scheduler manages state — generators are pure
let balance = 100;
const g1 = pureDeductGen(balance, 30);
const { value: r1 } = g1.next();
if (r1.ok) balance = r1.balance;
// balance is authoritative — no race
```

Prefetching starts loading data before it is needed — during idle time or as user signals intent (hover, focus). When data is actually needed, it resolves instantly from the in-flight or completed promise.

```javascript
class Prefetcher {
  #cache = new Map();

  prefetch(key, fetcher) {
    if (!this.#cache.has(key)) {
      // Start fetch — store promise (not just result)
      const promise = fetcher().catch(err => {
        this.#cache.delete(key); // don't cache errors
        throw err;
      });
      this.#cache.set(key, promise);
    }
    return this.#cache.get(key);
  }

  get(key, fetcher) {
    if (this.#cache.has(key)) {
      return this.#cache.get(key); // instant resolve if prefetched
    }
    return this.prefetch(key, fetcher); // fetch on demand
  }

  invalidate(key) { this.#cache.delete(key); }
}

const prefetcher = new Prefetcher();

// Prefetch on hover — user hasn't clicked yet
navLink.addEventListener('mouseenter', () => {
  prefetcher.prefetch('page:about', () => fetch('/api/about').then(r => r.json()));
});

// On click — instant (already prefetching or complete)
navLink.addEventListener('click', async () => {
  const data = await prefetcher.get('page:about',
    () => fetch('/api/about').then(r => r.json())
  );
  renderPage(data);
});
```

Route-based prefetching:
```javascript
// Prefetch all links visible in current viewport
const linkObserver = new IntersectionObserver((entries) => {
  entries
    .filter(e => e.isIntersecting)
    .forEach(e => {
      const href = e.target.getAttribute('href');
      if (href) {
        prefetcher.prefetch(`route:${href}`, () =>
          fetch(`/api/data${href}`).then(r => r.json())
        );
      }
    });
});

document.querySelectorAll('a[href]').forEach(a => linkObserver.observe(a));
```

Long-running async workflows can be interrupted (network failure, process restart). Checkpointing saves progress at each stage so the workflow can resume from last checkpoint instead of restarting.

```javascript
class CheckpointedWorkflow {
  #checkpoints;
  #workflowId;

  constructor(workflowId, persistFn, loadFn) {
    this.#workflowId = workflowId;
    this.persist = persistFn;
    this.load = loadFn;
  }

  async run(stages) {
    // Load existing checkpoint
    const saved = await this.load(this.#workflowId) ?? { stage: 0, data: {} };
    let { stage: startStage, data: ctx } = saved;

    console.log(`Resuming workflow from stage ${startStage}/${stages.length}`);

    for (let i = startStage; i < stages.length; i++) {
      const { name, fn } = stages[i];
      try {
        console.log(`Running stage ${i}: ${name}`);
        ctx = { ...ctx, ...(await fn(ctx)) };

        // Save checkpoint after each successful stage
        await this.persist(this.#workflowId, { stage: i + 1, data: ctx });
        console.log(`Stage ${name} complete — checkpoint saved`);
      } catch (err) {
        console.error(`Stage ${name} failed:`, err);
        throw err; // will resume from this stage on next run
      }
    }

    await this.persist(this.#workflowId, null); // clear checkpoint
    return ctx;
  }
}

// Data migration workflow:
const migration = new CheckpointedWorkflow(
  'migration-2024-01',
  (id, data) => db.save('checkpoints', id, data),
  (id) => db.load('checkpoints', id)
);

const result = await migration.run([
  { name: 'export',    fn: (ctx) => exportOldData().then(data => ({ data })) },
  { name: 'transform', fn: (ctx) => transformData(ctx.data).then(rows => ({ rows })) },
  { name: 'validate',  fn: (ctx) => validateRows(ctx.rows).then(valid => ({ valid })) },
  { name: 'import',    fn: (ctx) => importData(ctx.valid).then(count => ({ count })) },
]);
```

Adding event listeners in async callbacks or loops without cleanup creates multiple duplicate listeners and memory leaks — especially dangerous in long-running apps.

Bug — duplicate listener accumulation:
```javascript
async function setupHandlers() {
  const data = await fetchConfig();
  // Called multiple times (e.g., on re-render) — adds ANOTHER listener each time!
  window.addEventListener('resize', () => handleResize(data));
  document.addEventListener('click', () => handleClick(data));
  // Listeners accumulate — old ones never removed
}

// Called 10 times = 10 resize handlers, all with potentially stale data
```

Fix — track and remove before re-adding:
```javascript
let resizeHandler = null;
let clickHandler = null;

async function setupHandlers() {
  const data = await fetchConfig();

  // Remove old listener before adding new
  if (resizeHandler) window.removeEventListener('resize', resizeHandler);
  if (clickHandler) document.removeEventListener('click', clickHandler);

  resizeHandler = () => handleResize(data);
  clickHandler = () => handleClick(data);

  window.addEventListener('resize', resizeHandler);
  document.addEventListener('click', clickHandler);
}
```

Fix — AbortSignal for listener cleanup:
```javascript
let setupController = null;

async function setupHandlers() {
  setupController?.abort(); // remove previous listeners
  setupController = new AbortController();
  const signal = setupController.signal;

  const data = await fetchConfig();
  if (signal.aborted) return; // config fetch was cancelled

  window.addEventListener('resize', () => handleResize(data), { signal });
  document.addEventListener('click', () => handleClick(data), { signal });
  // All listeners removed automatically when signal aborts
}
```

Fix — once option for single-use listeners:
```javascript
// Listener fires exactly once — auto-removed
element.addEventListener('click', handler, { once: true });
```

Distributed lock with a TTL lease — lock holder must periodically renew to keep the lock. If holder crashes, lock expires and another process can acquire it.

```javascript
class DistributedLock {
  #name;
  #ttlMs;
  #renewalIntervalMs;
  #lockId = null;
  #renewalTimer = null;

  constructor(name, { ttlMs = 30000, renewalMs = 10000 } = {}) {
    this.#name = name;
    this.#ttlMs = ttlMs;
    this.#renewalIntervalMs = renewalMs;
  }

  async acquire() {
    this.#lockId = crypto.randomUUID();
    const acquired = await this.#tryAcquire();
    if (!acquired) throw new Error(`Lock '${this.#name}' is held by another process`);
    this.#startRenewal();
    return this;
  }

  async #tryAcquire() {
    return redis.set(
      `lock:${this.#name}`,
      this.#lockId,
      { NX: true, PX: this.#ttlMs } // NX: only if not exists, PX: TTL in ms
    );
  }

  #startRenewal() {
    this.#renewalTimer = setInterval(async () => {
      try {
        await this.#renew();
      } catch (err) {
        console.error('Lock renewal failed — releasing:', err);
        await this.release();
      }
    }, this.#renewalIntervalMs);
  }

  async #renew() {
    const currentHolder = await redis.get(`lock:${this.#name}`);
    if (currentHolder !== this.#lockId) throw new Error('Lock stolen');
    await redis.pexpire(`lock:${this.#name}`, this.#ttlMs);
  }

  async release() {
    clearInterval(this.#renewalTimer);
    this.#renewalTimer = null;
    // Only release if still our lock (avoid releasing another process's lock)
    const script = `
      if redis.call('get', KEYS[1]) == ARGV[1] then
        return redis.call('del', KEYS[1])
      else return 0 end`;
    await redis.eval(script, { keys: [`lock:${this.#name}`], args: [this.#lockId] });
  }
}

const lock = new DistributedLock('job-processor', { ttlMs: 30000 });
try {
  await lock.acquire();
  await processLongRunningJob(); // lock renews every 10s
} finally {
  await lock.release();
}
```

Throttle limits how often a function runs. Debounce delays execution until after a quiet period. Both prevent concurrent async operation overload.

Debounce — wait for pause before executing:
```javascript
function debounce(fn, delay) {
  let timer = null;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

// Search only after user stops typing for 300ms
const debouncedSearch = debounce(async (query) => {
  const results = await fetch(`/api/search?q=${query}`).then(r => r.json());
  renderResults(results);
}, 300);

inputEl.addEventListener('input', (e) => debouncedSearch(e.target.value));
```

Throttle — execute at most once per interval:
```javascript
function throttle(fn, interval) {
  let lastCall = 0;
  return function(...args) {
    const now = Date.now();
    if (now - lastCall >= interval) {
      lastCall = now;
      return fn.apply(this, args);
    }
  };
}

// Save at most once per second even if called frequently
const throttledSave = throttle(async () => {
  await saveDocument(currentContent);
}, 1000);

document.addEventListener('keyup', throttledSave);
```

Async-aware debounce (returns promise):
```javascript
function asyncDebounce(fn, delay) {
  let timer = null;
  let pendingResolve = null;

  return function(...args) {
    clearTimeout(timer);
    return new Promise((resolve) => {
      pendingResolve = resolve;
      timer = setTimeout(async () => {
        const result = await fn.apply(this, args);
        pendingResolve(result);
      }, delay);
    });
  };
}
```

In RxJS, forkJoin is the exact equivalent of Promise.all. It waits for all passed Observables to complete and then emits an array or object with the final values. Useful for parallel API requests.
```javascript
import { forkJoin, ajax } from 'rxjs';

forkJoin({
  data1: ajax.getJSON('/api/data1'),
  data2: ajax.getJSON('/api/data2')
}).subscribe(console.log);
```

Unlike Promise.all which fires all promises at once, RxJS mergeMap allows you to specify a concurrency limit. This prevents overwhelming the server or memory when processing thousands of items.
```javascript
import { from } from 'rxjs';
import { mergeMap } from 'rxjs/operators';

from(largeArray).pipe(
  // Only run 5 concurrent HTTP requests
  mergeMap(item => processItemAsynchronously(item), 5)
).subscribe();
```

p-limit is a tiny third-party library to limit concurrent promise executions. It's often used when Promise.all is too aggressive and you need to batch operations.
```javascript
import pLimit from 'p-limit';

const limit = pLimit(5); // Max 5 concurrent promises
const input = [1, 2, 3, 4, 5, 6, 7];

const promises = input.map(i => limit(() => fetchSomething(i)));
await Promise.all(promises);
```

Node.js is single-threaded, but asynchronous operations can interleave and cause race conditions. The 'async-mutex' library provides a Mutex to lock critical sections of async code.
```javascript
import { Mutex } from 'async-mutex';
const mutex = new Mutex();

async function safeUpdate(id) {
  const release = await mutex.acquire();
  try {
    const data = await db.read(id);
    await db.write(id, data + 1);
  } finally {
    release();
  }
}
```

Bluebird is a powerful Promise library. Promise.map allows iterating over an array with an async mapper function, with a built-in concurrency limit option, making it safer than native Promise.all for large arrays.
```javascript
import Promise from 'bluebird';

await Promise.map(items, async (item) => {
  return await processItem(item);
}, { concurrency: 3 }); // Only 3 active promises at a time
```

