  const response = await fetch('/api/data');
  data = await response.json(); // modifies shared state
}

loadData(); // NOT awaited — fire and forget
console.log(data); // null — loadData hasn't finished yet

async function processAll() {
  loadData();       // fire-and-forget
  loadMoreData();   // fire-and-forget
  processData();    // runs before either load completes
}
```

FIX — always await or chain:
```javascript
async function processAll() {
  await Promise.all([loadData(), loadMoreData()]);
  processData(); // runs after both loads complete
}
```

FIX — if intentional background task, handle errors explicitly:
```javascript
void loadData().catch((err) => console.error('Background task failed:', err));
```

WARNING: Unhandled promise rejections from fire-and-forget will be silently ignored (or crash Node.js). Always attach a .catch() if not awaiting.

