A worker pool maintains multiple workers and queues tasks, preventing bottlenecks from single-worker serialization and avoiding thread creation overhead per task.

```javascript
class WorkerPool {
  constructor(workerScript, size = navigator.hardwareConcurrency || 4) {
    this.workers = Array.from({ length: size }, () => ({
      worker: new Worker(workerScript),
      busy: false,
    }));
    this.queue = [];
  }

  run(data) {
    return new Promise((resolve, reject) => {
      const free = this.workers.find((w) => !w.busy);
      if (free) {
        this._dispatch(free, data, resolve, reject);
      } else {
        this.queue.push({ data, resolve, reject });
      }
