JavaScript is single-threaded in the main thread, but async code can create logical races. A mutex serializes access to a critical section across async operations.

Mutex implementation:
```javascript
class Mutex {
  constructor() {
    this._queue = [];
    this._locked = false;
  }

  lock() {
    return new Promise((resolve) => {
      if (!this._locked) {
        this._locked = true;
        resolve();
      } else {
        this._queue.push(resolve);
      }
    });
  }

  unlock() {
    if (this._queue.length > 0) {
      const next = this._queue.shift();
      next();
    } else {
      this._locked = false;
    }
  }

  async runExclusive(fn) {
    await this.lock();
    try {
      return await fn();
    } finally {
      this.unlock();
    }
  }
}

// Usage
const mutex = new Mutex();
let sharedCounter = 0;

async function safeIncrement() {
  await mutex.runExclusive(async () => {
    const current = sharedCounter;
    await someAsyncWork();
    sharedCounter = current + 1; // safe — no other fn runs during await
  });
}

await Promise.all([safeIncrement(), safeIncrement(), safeIncrement()]);
console.log(sharedCounter); // always 3
```

Semaphore (limit concurrent access to N):
```javascript
class Semaphore {
  constructor(max) {
    this._max = max;
    this._count = 0;
    this._queue = [];
  }

  async acquire() {
    if (this._count < this._max) {
      this._count++;
      return;
    }
    await new Promise((resolve) => this._queue.push(resolve));
    this._count++;
  }

  release() {
    this._count--;
    if (this._queue.length > 0) this._queue.shift()();
  }
}

// Limit to 3 concurrent API calls
const sem = new Semaphore(3);
async function rateLimitedFetch(url) {
  await sem.acquire();
  try { return await fetch(url); }
  finally { sem.release(); }
}
```

