Node.js worker_threads module provides real OS-level threads for CPU-bound tasks. Unlike Web Workers, they can share memory via SharedArrayBuffer and have access to Node.js APIs.

```javascript
const { Worker, isMainThread, parentPort, workerData, threadId } = require('worker_threads');

if (isMainThread) {
  // Main thread — spawn workers
  function runWorker(data) {
    return new Promise((resolve, reject) => {
      const worker = new Worker(__filename, { workerData: data });
      worker.on('message', resolve);
      worker.on('error', reject);
      worker.on('exit', (code) => {
        if (code !== 0) reject(new Error(`Worker stopped with exit code ${code}`));
      });
    });
  }

  async function main() {
    const results = await Promise.all([
      runWorker({ start: 0, end: 250000 }),
      runWorker({ start: 250000, end: 500000 }),
      runWorker({ start: 500000, end: 750000 }),
      runWorker({ start: 750000, end: 1000000 }),
    ]);
    console.log('All workers done:', results);
  }

  main();
} else {
  // Worker thread — do the work
  const { start, end } = workerData;
  console.log(`Worker ${threadId} processing ${start}-${end}`);
  const result = computeRange(start, end);
  parentPort.postMessage(result);
}
```

