Async iterators and for-await-of enable processing streams of data as they arrive without buffering all in memory.

```javascript
// Async iterable from paginated API
async function* fetchAllPages(baseUrl) {
  let page = 1;
  let hasMore = true;

  while (hasMore) {
    const response = await fetch(`${baseUrl}?page=${page}`);
    const data = await response.json();
    yield data.items;
    hasMore = data.hasNextPage;
    page++;
  }
}

// Process as data arrives — no need to load all pages first
for await (const items of fetchAllPages('/api/users')) {
  await processItems(items);
  console.log(`Processed ${items.length} users`);
}
```

Async generator with backpressure:
```javascript
async function* rateLimited(iterable, delayMs) {
  for await (const item of iterable) {
    yield item;
    await new Promise((resolve) => setTimeout(resolve, delayMs));
  }
}

for await (const item of rateLimited(dataSource, 100)) {
  await processItem(item); // at most 10 per second
}
```

Readable stream as async iterable (Node.js):
```javascript
const fs = require('fs');

async function readLines(filePath) {
  const stream = fs.createReadStream(filePath, { encoding: 'utf8' });
  let buffer = '';

  for await (const chunk of stream) {
    buffer += chunk;
    const lines = buffer.split('\n');
    buffer = lines.pop(); // keep partial line
    for (const line of lines) yield line;
  }
  if (buffer) yield buffer;
}

for await (const line of readLines('./large-file.txt')) {
  processLine(line);
}
```

