```javascript
// Tab 1 — Sender
const channel = new BroadcastChannel('app_state');
channel.postMessage({ type: 'USER_LOGGED_OUT', userId: '123' });

// Tab 2 — Receiver (same origin)
const channel = new BroadcastChannel('app_state');
channel.addEventListener('message', (event) => {
  if (event.data.type === 'USER_LOGGED_OUT') {
    clearUserSession();
    redirectToLogin();
  }
});

// Always clean up
channel.close();
```

