Symbol.asyncIterator defines how an object is async iterable. Implement [Symbol.asyncIterator]() to make any object usable with for-await-of.

Basic implementation:
```javascript
const asyncRange = {
  from: 1,
  to: 5,
  async *[Symbol.asyncIterator]() {
    for (let i = this.from; i <= this.to; i++) {
      await new Promise(r => setTimeout(r, 100)); // simulate async delay
      yield i;
    }
  }
};

for await (const num of asyncRange) {
  console.log(num); // 1, 2, 3, 4, 5 with 100ms delays
}
```

From scratch (full protocol):
```javascript
const paginatedAPI = {
  [Symbol.asyncIterator]() {
    let page = 1;
    return {
      async next() {
        const res = await fetch(`/api/items?page=${page}`);
        const { items, hasMore } = await res.json();
        page++;
        if (items.length === 0) return { done: true, value: undefined };
        return { done: !hasMore && items.length === 0, value: items };
      },
      async return() {
        return { done: true, value: undefined }; // cleanup on break
      }
    };
  }
};

for await (const page of paginatedAPI) {
  renderItems(page);
}
```

