inputEl.addEventListener('input', async (e) => {
  const results = await searchAPI(e.target.value);
  renderResults(results); // may render results from earlier query
});
// User types 'a', then 'ab' — 'a' results arrive after 'ab' results
// UI shows wrong 'a' results
```

FIX 1 — cancel previous request (AbortController):
```javascript
let currentController = null;

inputEl.addEventListener('input', async (e) => {
  currentController?.abort();
  currentController = new AbortController();
  try {
    const results = await searchAPI(e.target.value, {
      signal: currentController.signal
    });
    renderResults(results);
  } catch (err) {
    if (err.name !== 'AbortError') throw err;
  }
});
```

FIX 2 — generation counter (ignore stale responses):
```javascript
let requestId = 0;

inputEl.addEventListener('input', async (e) => {
  const id = ++requestId;
  const results = await searchAPI(e.target.value);
  if (id !== requestId) return; // stale — newer request pending
  renderResults(results);
});
```

FIX 3 — debounce + AbortController combined (best practice):
```javascript
const debouncedSearch = debounce(async (query, signal) => {
  const results = await searchAPI(query, { signal });
  renderResults(results);
}, 300);
```

**Scenario (Healthcare):** Implementing this pattern to handle patients efficiently.

When multiple async operations are in flight (e.g., user types quickly), earlier requests may resolve after newer ones — overwriting the correct (newer) result with stale data.

