A worker pool maintains a fixed number of Web Workers and distributes tasks among them. Avoids overhead of creating/destroying workers per task.

```javascript
class WorkerPool {
  constructor(workerScript, size) {
    this.workers = Array.from(
      { length: size },
      () => ({
        worker: new Worker(workerScript),
        busy: false,
      })
    );
    this.queue = [];
  }

  run(data) {
    return new Promise((resolve, reject) => {
      const task = { data, resolve, reject };
      const slot = this.workers.find(w => !w.busy);
      if (slot) {
        this._dispatch(slot, task);
      } else {
        this.queue.push(task);
      }
    });
  }

  _dispatch(slot, task) {
    slot.busy = true;
    slot.worker.onmessage = (e) => {
      task.resolve(e.data);
      slot.busy = false;
      const next = this.queue.shift();
      if (next) this._dispatch(slot, next);
    };
    slot.worker.onerror = (err) => {
      task.reject(err);
      slot.busy = false;
    };
    slot.worker.postMessage(task.data);
  }

  terminate() {
    this.workers.forEach(({ worker }) => worker.terminate());
  }
}

const pool = new WorkerPool('./compute-worker.js', navigator.hardwareConcurrency);
const results = await Promise.all(tasks.map(t => pool.run(t)));
pool.terminate();
```

