When a module or class requires async setup, guard against usage before initialization completes using a deferred promise.

Problem — initialization race:
```javascript
class Database {
  constructor() {
    this.connection = null;
    this.connect(); // async — might not be done before first query()
  }

  async connect() { this.connection = await openConnection(); }
  async query(sql) { return this.connection.query(sql); } // null if called too early
}
```

Fix — ready promise:
```javascript
class Database {
  constructor(config) {
    const { promise, resolve, reject } = Promise.withResolvers();
    this._ready = promise;

    openConnection(config)
      .then(conn => { this._conn = conn; resolve(); })
      .catch(reject);
  }

  async query(sql) {
    await this._ready; // wait for initialization
    return this._conn.query(sql);
  }

  async close() {
    await this._ready;
    await this._conn.close();
  }
}

const db = new Database(config); // starts connecting
await db.query('SELECT 1'); // waits for connection automatically
```

Singleton with async factory:
```javascript
let _instancePromise = null;

async function getInstance() {
  if (!_instancePromise) {
    _instancePromise = createExpensiveInstance();
  }
  return _instancePromise; // all callers share same promise
}

// Multiple callers — all await the same initialization
const [a, b, c] = await Promise.all([getInstance(), getInstance(), getInstance()]);
// createExpensiveInstance called exactly once
```

