Process events asynchronously with bounded concurrency — prevent memory accumulation when producers emit faster than consumers can process.

```javascript
class AsyncQueue {
  constructor(concurrency = 1) {
    this.concurrency = concurrency;
    this.running = 0;
    this.queue = [];
  }

  push(task) {
    return new Promise((resolve, reject) => {
      this.queue.push({ task, resolve, reject });
      this._drain();
    });
  }

  _drain() {
    while (this.running < this.concurrency && this.queue.length > 0) {
      const { task, resolve, reject } = this.queue.shift();
      this.running++;
      Promise.resolve()
        .then(() => task())
        .then(resolve, reject)
        .finally(() => {
          this.running--;
          this._drain();
        });
    }
  }
}

const queue = new AsyncQueue(3); // max 3 concurrent

// Producer can push many items — queue manages concurrency
const results = await Promise.all(
  incomingEvents.map(event => queue.push(() => processEvent(event)))
);
```

With bounded buffer (backpressure — push returns pending when buffer full):
```javascript
class BoundedQueue {
  constructor(maxSize, concurrency) {
    this.maxSize = maxSize;
    this.inner = new AsyncQueue(concurrency);
    this.pendingPushes = [];
  }

  async push(task) {
    while (this.inner.queue.length >= this.maxSize) {
      await new Promise(r => this.pendingPushes.push(r));
    }
    return this.inner.push(task).finally(() => {
      this.pendingPushes.shift()?.();
    });
  }
}
```

