Observable pattern enables push-based async data streams with lazy subscription. Composable, cancellable alternative to event emitters for async sequences.

Manual Observable implementation:
```javascript
class Observable {
  constructor(subscriber) {
    this._subscriber = subscriber;
  }

  subscribe(observer) {
    const { next, error, complete } = observer;
    let cancelled = false;

    this._subscriber({
      next: v => !cancelled && next?.(v),
      error: e => !cancelled && error?.(e),
      complete: () => !cancelled && complete?.(),
    });

    return { unsubscribe: () => { cancelled = true; } };
  }

  map(fn) {
    return new Observable(obs =>
      this.subscribe({
        next: v => obs.next(fn(v)),
        error: obs.error,
        complete: obs.complete,
      })
    );
  }

  filter(pred) {
    return new Observable(obs =>
      this.subscribe({
        next: v => pred(v) && obs.next(v),
        error: obs.error,
        complete: obs.complete,
      })
    );
  }
}

// From WebSocket
const messages = new Observable(obs => {
  const ws = new WebSocket('wss://api/stream');
  ws.onmessage = e => obs.next(JSON.parse(e.data));
  ws.onerror = e => obs.error(e);
  ws.onclose = () => obs.complete();
});

const subscription = messages
  .filter(msg => msg.type === 'UPDATE')
  .map(msg => msg.payload)
  .subscribe({ next: updateUI, error: console.error });

// Cancel
subscription.unsubscribe();
```

