**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Chain async processing stages where output of one stage feeds input of the next. Each stage can have different concurrency limits.

```javascript
async function* pipeline(source, ...stages) {
  let current = source;
  for (const stage of stages) {
    current = stage(current);
  }
  yield* current;
}

// Stage factory with concurrency
function concurrentMap(fn, concurrency = 1) {
  return async function*(source) {
    const inFlight = [];

    for await (const item of source) {
      const p = fn(item);
      inFlight.push(p);

      if (inFlight.length >= concurrency) {
        yield await inFlight.shift();
      }
    }

    // drain remaining
    for (const p of inFlight) yield await p;
  };
}

function asyncFilter(pred) {
  return async function*(source) {
    for await (const item of source) {
      if (await pred(item)) yield item;
    }
  };
}

// Usage
async function* rawItems() {
  for (const id of itemIds) yield id;
}

for await (const result of pipeline(
  rawItems(),
  concurrentMap(fetchItem, 5),        // fetch 5 at a time
  asyncFilter(item => item.active),   // filter
  concurrentMap(processItem, 3),      // process 3 at a time
)) {
  saveResult(result);
}
```

