**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

WebSocket messages arrive as events — bridge to async/await with a message queue that yields messages as they arrive.

```javascript
class AsyncWebSocket {
  constructor(url) {
    this.ws = new WebSocket(url);
    this.queue = [];
    this.resolvers = [];
    this._closed = false;
    this._closedReason = null;
    this._setup();
  }

  _setup() {
    this.ws.onmessage = (e) => {
      const data = JSON.parse(e.data);
      if (this.resolvers.length > 0) {
        this.resolvers.shift()(data);
      } else {
        this.queue.push(data);
      }
    };
    this.ws.onclose = () => {
      this._closed = true;
      this.resolvers.forEach(r => r(null)); // wake all waiters
    };
    this.ws.onerror = (err) => {
      this._closedReason = err;
      this.ws.close();
    };
  }

  receive() {
    if (this.queue.length > 0) return Promise.resolve(this.queue.shift());
    if (this._closed) return Promise.resolve(null);
    return new Promise(resolve => this.resolvers.push(resolve));
  }

  send(data) {
    this.ws.send(JSON.stringify(data));
  }

  async *messages() {
    while (!this._closed) {
      const msg = await this.receive();
      if (msg === null) break;
      yield msg;
    }
  }
}

const ws = new AsyncWebSocket('wss://api/stream');
await new Promise(r => ws.ws.addEventListener('open', r));

for await (const msg of ws.messages()) {
  handleMessage(msg);
}
```

