WeakMap stores metadata keyed by object reference — automatically GC'd when key object is collected. Ideal for per-object locking and private state in async classes.

Per-object mutex:
```javascript
const mutexes = new WeakMap();

function getMutex(obj) {
  if (!mutexes.has(obj)) mutexes.set(obj, Promise.resolve());
  return mutexes.get(obj);
}

async function withObjectLock(obj, fn) {
  const current = getMutex(obj);
  const next = current.then(() => fn());
  mutexes.set(obj, next.catch(() => {})); // next lock doesn't inherit error
  return next;
}

const resource = { value: 0 };

await Promise.all([
  withObjectLock(resource, async () => { resource.value += 1; }),
  withObjectLock(resource, async () => { resource.value += 1; }),
  withObjectLock(resource, async () => { resource.value += 1; }),
]);
// resource.value === 3 — serialized
// When resource is GC'd, mutex entry auto-removed
```

Private async state:
```javascript
const _state = new WeakMap();

class AsyncProcessor {
  constructor() {
    _state.set(this, { queue: [], processing: false });
  }

  async enqueue(item) {
    const state = _state.get(this);
    state.queue.push(item);
    if (!state.processing) {
      state.processing = true;
      await this._process(state);
      state.processing = false;
    }
  }

  async _process(state) {
    while (state.queue.length > 0) {
      await processItem(state.queue.shift());
    }
  }
}
```

