**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Model complex async workflows as explicit state machines — each state defines valid transitions and async operations. Prevents invalid concurrent state mutations.

```javascript
const STATES = { IDLE: 'idle', LOADING: 'loading', SUCCESS: 'success', ERROR: 'error' };

class AsyncStateMachine {
  constructor() {
    this.state = STATES.IDLE;
    this.data = null;
    this.error = null;
    this._listeners = new Set();
  }

  _transition(newState, payload = {}) {
    this.state = newState;
    Object.assign(this, payload);
    this._listeners.forEach(fn => fn(this.state, this));
  }

  async load(fetchFn) {
    if (this.state === STATES.LOADING) return; // guard concurrent calls

    this._transition(STATES.LOADING);
    try {
      const data = await fetchFn();
      this._transition(STATES.SUCCESS, { data, error: null });
    } catch (error) {
      this._transition(STATES.ERROR, { error, data: null });
    }
  }

  reset() {
    if (this.state === STATES.LOADING) return; // cannot reset while loading
    this._transition(STATES.IDLE, { data: null, error: null });
  }

  subscribe(listener) {
    this._listeners.add(listener);
    return () => this._listeners.delete(listener); // unsubscribe
  }
}

const machine = new AsyncStateMachine();
machine.subscribe((state, ctx) => renderUI(state, ctx.data, ctx.error));

await machine.load(() => fetch('/api/data').then(r => r.json()));
```

