Cache stampede: cache expires, multiple concurrent requests all miss, all trigger expensive backend calls simultaneously — overwhelming the data source.

PROBLEM:
```javascript
let cache = null;
let cacheExpiry = 0;

async function getData() {
  if (cache && Date.now() < cacheExpiry) return cache;

  // All concurrent callers miss simultaneously
  const data = await expensiveDBQuery(); // called N times
  cache = data;
  cacheExpiry = Date.now() + 60000;
  return data;
}

// 100 concurrent requests at expiry time → 100 DB queries
await Promise.all(Array.from({ length: 100 }, () => getData()));
```

FIX — promise-based cache (only one fetch regardless of concurrency):
```javascript
let cachePromise = null;
let cacheExpiry = 0;

async function getData() {
  if (cachePromise && Date.now() < cacheExpiry) return cachePromise;

  // All share one promise — one DB query
  cachePromise = expensiveDBQuery();
  cacheExpiry = Date.now() + 60000;

  cachePromise.catch(() => {
    cachePromise = null; // allow retry on failure
  });

  return cachePromise;
}

// 100 concurrent requests → 1 DB query
await Promise.all(Array.from({ length: 100 }, () => getData()));
```

FIX — stale-while-revalidate:
```javascript
async function getData() {
  if (cache && Date.now() < softExpiry) return cache; // fresh
  if (cache) {
    refreshInBackground(); // return stale, refresh async
    return cache;
  }
  cache = await expensiveDBQuery(); // cold start only
  return cache;
}
```

