A mutex that rejects if the lock cannot be acquired within a timeout — prevents deadlock from hanging indefinitely.

```javascript
class TimedMutex {
  constructor() {
    this._queue = Promise.resolve();
    this._locked = false;
  }

  async lock(timeoutMs = 5000) {
    let unlock;
    const lockPromise = new Promise(resolve => { unlock = resolve; });

    const timeoutPromise = new Promise((_, reject) =>
      setTimeout(() => reject(new Error(`Mutex timeout after ${timeoutMs}ms`)), timeoutMs)
    );

    const prevQueue = this._queue;
    this._queue = this._queue.then(() => lockPromise);

    await Promise.race([prevQueue, timeoutPromise]);

    return () => unlock(); // return release function
  }
}

const mutex = new TimedMutex();

async function criticalSection() {
  let release;
  try {
    release = await mutex.lock(3000); // wait max 3s
    await doExclusiveWork();
  } catch (err) {
    if (err.message.includes('Mutex timeout')) {
      console.error('Could not acquire lock in time');
    }
    throw err;
  } finally {
    release?.(); // always release
  }
}
```

Simpler version using Web Locks API:
```javascript
async function withTimedLock(name, fn, timeoutMs = 5000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    return await navigator.locks.request(
      name,
      { signal: controller.signal },
      async (lock) => fn()
    );
  } finally {
    clearTimeout(timer);
  }
}
```

