async function withTimedLock(name, fn, timeoutMs = 5000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    return await navigator.locks.request(
      name,
      { signal: controller.signal },
      async (lock) => fn()
    );
  } finally {
    clearTimeout(timer);
  }
}
