Split large file processing across multiple workers — divide data by range, process concurrently, merge results.

```javascript
// main.js
async function processLargeFile(fileContent) {
  const WORKER_COUNT = navigator.hardwareConcurrency || 4;
  const lines = fileContent.split('\n');
  const chunkSize = Math.ceil(lines.length / WORKER_COUNT);

  const workers = Array.from({ length: WORKER_COUNT }, () =>
    new Worker('./file-processor.js')
  );

  function runWorker(worker, chunk) {
    return new Promise((resolve, reject) => {
      worker.onmessage = e => resolve(e.data);
      worker.onerror = e => reject(e);
      worker.postMessage({ lines: chunk });
    });
  }

  const chunks = Array.from({ length: WORKER_COUNT }, (_, i) =>
    lines.slice(i * chunkSize, (i + 1) * chunkSize)
  );

  const partialResults = await Promise.all(
    workers.map((worker, i) => runWorker(worker, chunks[i]))
  );

  workers.forEach(w => w.terminate());

  return mergeResults(partialResults);
}

// file-processor.js
onmessage = (e) => {
  const { lines } = e.data;
  const result = lines
    .filter(line => line.trim())
    .map(parseLine)
    .reduce(aggregate, initialState);
  postMessage(result);
};
```

