**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

When some requests depend on others, model dependencies explicitly and run independent requests in parallel while awaiting dependencies.

```javascript
async function fetchDashboard(userId) {
  // Layer 1: Independent — run all at once
  const [user, config] = await Promise.all([
    fetch(`/api/users/${userId}`).then(r => r.json()),
    fetch('/api/config').then(r => r.json()),
  ]);

  // Layer 2: Depends on Layer 1 — run independently within layer
  const [orders, preferences, permissions] = await Promise.all([
    fetch(`/api/orders?userId=${user.id}`).then(r => r.json()),
    fetch(`/api/prefs?userId=${user.id}&theme=${config.defaultTheme}`).then(r => r.json()),
    fetch(`/api/permissions?role=${user.role}`).then(r => r.json()),
  ]);

  // Layer 3: Depends on Layer 2
  const [orderDetails, allowedActions] = await Promise.all([
    Promise.all(orders.slice(0, 5).map(o =>
      fetch(`/api/orders/${o.id}/details`).then(r => r.json())
    )),
    filterActionsByPermissions(permissions),
  ]);

  return { user, config, orders, orderDetails, preferences, allowedActions };
}
```

Graph-based executor:
```javascript
async function executeDAG(tasks) {
  const results = new Map();
  const pending = new Map();

  async function execute(id) {
    if (results.has(id)) return results.get(id);
    if (pending.has(id)) return pending.get(id);

    const task = tasks[id];
    const deps = await Promise.all((task.deps || []).map(execute));
    const promise = task.fn(...deps);
    pending.set(id, promise);
    const result = await promise;
    results.set(id, result);
    return result;
  }

  await Promise.all(Object.keys(tasks).map(execute));
  return Object.fromEntries(results);
}
```

