  const tasks = new Set();

  const scope = {
    signal: controller.signal,
    spawn(asyncFn) {
      const task = asyncFn(controller.signal);
      tasks.add(task);
      task.finally(() => tasks.delete(task));
      return task;
    },
  };

  try {
    return await fn(scope);
  } finally {
    controller.abort(); // cancel all children on exit
    await Promise.allSettled([...tasks]); // wait for cleanup
  }
}

// Usage: all tasks auto-cancelled when withScope returns or throws
const result = await withScope(async (scope) => {
  const [a, b] = await Promise.all([
    scope.spawn(sig => fetch('/api/a', { signal: sig }).then(r => r.json())),
    scope.spawn(sig => fetch('/api/b', { signal: sig }).then(r => r.json())),
  ]);
  return combine(a, b);
}); // on any error: both fetches cancelled
```

With individual task timeouts:
```javascript
await withScope(async (scope) => {
  const combined = AbortSignal.any([
    scope.signal,
    AbortSignal.timeout(5000)
  ]);
  return fetch('/api/slow', { signal: combined }).then(r => r.json());
});
```

