Adding event listeners inside async operations without cleanup causes multiple listeners to fire for each event — each async call adds another layer.

PROBLEM — multiple listeners from repeated calls:
```javascript
async function setupWebSocket() {
  const ws = new WebSocket(url);

  ws.addEventListener('message', (e) => {
    updateUI(JSON.parse(e.data));
  });

  // If setupWebSocket is called again (reconnect), another listener is added
  // Both fire for every message — UI updated twice, possibly with stale closure
}

// Called on reconnect:
await setupWebSocket(); // 1st listener
await setupWebSocket(); // 2nd listener — now 2 handlers fire per message
```

FIX — named function + removeEventListener:
```javascript
function setupWebSocket() {
  const ws = new WebSocket(url);

  function handleMessage(e) {
    updateUI(JSON.parse(e.data));
  }

  ws.addEventListener('message', handleMessage);

  return () => {
    ws.removeEventListener('message', handleMessage);
    ws.close();
  };
}

let cleanup = setupWebSocket();
// On reconnect:
cleanup(); // remove old listeners
cleanup = setupWebSocket(); // fresh listener only
```

FIX — { once: true } for single-fire listeners:
```javascript
ws.addEventListener('open', () => sendInitialData(), { once: true });
// Automatically removed after first fire
```

FIX — AbortController for bulk removal:
```javascript
const controller = new AbortController();
ws.addEventListener('message', handler, { signal: controller.signal });
ws.addEventListener('error', errHandler, { signal: controller.signal });

// Remove all at once:
controller.abort();
```

