WebSocket provides full-duplex communication over a persistent connection. Unlike HTTP, both sides can send messages at any time.

Connection lifecycle:
```javascript
const ws = new WebSocket('wss://api.example.com/stream');

// readyState: CONNECTING(0) → OPEN(1) → CLOSING(2) → CLOSED(3)

ws.addEventListener('open', () => {
  ws.send(JSON.stringify({ type: 'SUBSCRIBE', channel: 'prices' }));
});

ws.addEventListener('message', (e) => {
  const data = JSON.parse(e.data);
  handleMessage(data);
});

ws.addEventListener('error', (e) => {
  console.error('WebSocket error');
});

ws.addEventListener('close', (e) => {
  console.log(`Closed: code=${e.code}, reason=${e.reason}`);
});

// Graceful close
ws.close(1000, 'Done');
```

Backpressure via bufferedAmount:
```javascript
function sendWhenReady(ws, data) {
  if (ws.bufferedAmount > 1024 * 64) {
    // Buffer full — wait before sending more
    setTimeout(() => sendWhenReady(ws, data), 100);
    return;
  }
  ws.send(data);
}
```

Auto-reconnect pattern:
```javascript
function createAutoReconnectWS(url) {
  let ws;
  let reconnectDelay = 1000;

  function connect() {
    ws = new WebSocket(url);
    ws.onopen = () => { reconnectDelay = 1000; };
    ws.onclose = (e) => {
      if (!e.wasClean) {
        setTimeout(connect, reconnectDelay);
        reconnectDelay = Math.min(reconnectDelay * 2, 30000);
      }
    };
    return ws;
  }

  return connect();
}
```

Binary data:
```javascript
ws.binaryType = 'arraybuffer';
ws.onmessage = (e) => {
  const buffer = e.data; // ArrayBuffer
  const view = new Int32Array(buffer);
};
```

