**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Resource pool maintains a bounded set of reusable resources (DB connections, HTTP clients, workers) — acquires from pool, uses, returns for next caller.

```javascript
class ResourcePool {
  constructor(factory, maxSize) {
    this.factory = factory;
    this.maxSize = maxSize;
    this.pool = []; // available resources
    this.waiters = []; // pending acquire() calls
    this.total = 0;
  }

  async acquire() {
    if (this.pool.length > 0) {
      return this.pool.pop();
    }

    if (this.total < this.maxSize) {
      this.total++;
      return await this.factory();
    }

    // Pool exhausted — wait for a resource to be released
    return new Promise((resolve) => this.waiters.push(resolve));
  }

  release(resource) {
    if (this.waiters.length > 0) {
      // Give directly to next waiter
      this.waiters.shift()(resource);
    } else {
      this.pool.push(resource);
    }
  }

  async use(fn) {
    const resource = await this.acquire();
    try {
      return await fn(resource);
    } finally {
      this.release(resource);
    }
  }
}

// DB connection pool
const dbPool = new ResourcePool(
  () => createDatabaseConnection(DB_URL),
  10 // max 10 connections
);

// All 100 requests share 10 connections
const results = await Promise.all(
  Array.from({ length: 100 }, (_, i) =>
    dbPool.use(conn => conn.query(`SELECT * FROM table WHERE id = ${i}`))
  )
);
```

