**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Memoize async functions — return cached promise for in-flight calls, cached value for completed calls. Prevents duplicate concurrent computations.

```javascript
function memoizeAsync(fn, options = {}) {
  const cache = new Map();
  const { ttl = Infinity, keyFn = (...args) => JSON.stringify(args) } = options;

  return async function(...args) {
    const key = keyFn(...args);
    const entry = cache.get(key);

    if (entry) {
      // Return cached promise (handles in-flight deduplication)
      if (Date.now() < entry.expiry) return entry.promise;
      cache.delete(key);
    }

    const promise = fn.apply(this, args).catch(err => {
      cache.delete(key); // remove on error — allow retry
      throw err;
    });

    cache.set(key, { promise, expiry: Date.now() + ttl });
    return promise;
  };
}

const fetchUser = memoizeAsync(
  async (id) => fetch(`/api/users/${id}`).then(r => r.json()),
  { ttl: 60000 } // 1 minute TTL
);

// All three share one fetch — even concurrent calls
const [a, b, c] = await Promise.all([
  fetchUser(1), // triggers fetch
  fetchUser(1), // returns same promise
  fetchUser(1), // returns same promise
]);
```

With WeakRef for automatic eviction:
```javascript
function memoizeWeakAsync(fn) {
  const cache = new Map();
  return async function(...args) {
    const key = JSON.stringify(args);
    const ref = cache.get(key);
    const cached = ref?.deref();
    if (cached !== undefined) return cached;

    const result = await fn.apply(this, args);
    cache.set(key, new WeakRef(result));
    return result;
  };
}
```

