**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Pub-sub decouples event publishers from subscribers — publishers emit events without knowing who listens; subscribers register interest without knowing the publisher.

```javascript
class PubSub {
  constructor() {
    this.subscribers = new Map();
  }

  subscribe(event, handler) {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, new Set());
    }
    this.subscribers.get(event).add(handler);

    // Return unsubscribe function
    return () => this.subscribers.get(event)?.delete(handler);
  }

  async publish(event, data) {
    const handlers = this.subscribers.get(event);
    if (!handlers) return;

    // All handlers run concurrently
    await Promise.allSettled(
      Array.from(handlers, handler => handler(data))
    );
  }

  once(event, handler) {
    const unsub = this.subscribe(event, async (data) => {
      unsub();
      return handler(data);
    });
    return unsub;
  }
}

const bus = new PubSub();

// Subscribe
const unsub = bus.subscribe('user.login', async (user) => {
  await updateSessionCache(user);
  await loadUserPreferences(user.id);
});

bus.subscribe('user.login', async (user) => {
  await sendWelcomeNotification(user);
});

// Publish — both handlers run concurrently
await bus.publish('user.login', { id: 1, name: 'Alice' });

// Unsubscribe
unsub();
```

