Rate limiter controls how many operations run per time window — prevents exceeding API rate limits or overwhelming services.

Token bucket rate limiter:
```javascript
class RateLimiter {
  constructor(maxRequests, windowMs) {
    this.maxRequests = maxRequests;
    this.windowMs = windowMs;
    this.queue = [];
    this.count = 0;
  }

  async acquire() {
    if (this.count < this.maxRequests) {
      this.count++;
      setTimeout(() => {
        this.count--;
        const next = this.queue.shift();
        if (next) next();
      }, this.windowMs);
      return;
    }

    // Wait for a slot to open
    return new Promise(resolve => this.queue.push(resolve))
      .then(() => this.acquire());
  }

  async run(fn) {
    await this.acquire();
    return fn();
  }
}

const limiter = new RateLimiter(10, 1000); // 10 req/sec

// 100 calls — all respect 10/sec limit
const results = await Promise.all(
  Array.from({ length: 100 }, (_, i) =>
    limiter.run(() => fetch(`/api/items/${i}`).then(r => r.json()))
  )
);
```

Simple sliding window:
```javascript
function createRateLimiter(maxPerSecond) {
  const timestamps = [];

  return async function rateLimit(fn) {
    const now = Date.now();
    const windowStart = now - 1000;
    while (timestamps.length && timestamps[0] < windowStart) timestamps.shift();

    if (timestamps.length >= maxPerSecond) {
      const waitMs = timestamps[0] + 1000 - now;
      await new Promise(r => setTimeout(r, waitMs));
      return rateLimit(fn);
    }

    timestamps.push(now);
    return fn();
  };
}
```

