**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Use generators to implement cooperative multitasking — tasks voluntarily yield control at yield points, allowing other tasks to run.

```javascript
class CoopScheduler {
  constructor() {
    this.tasks = [];
    this.running = false;
  }

  spawn(generatorFn, ...args) {
    this.tasks.push(generatorFn(...args));
    if (!this.running) this.run();
  }

  async run() {
    this.running = true;
    while (this.tasks.length > 0) {
      const task = this.tasks.shift();
      const { value, done } = task.next();

      if (!done) {
        this.tasks.push(task); // re-enqueue for next turn
      }

      if (value instanceof Promise) {
        await value; // yield on async operations
      } else {
        await Promise.resolve(); // yield to event loop
      }
    }
    this.running = false;
  }
}

const scheduler = new CoopScheduler();

function* taskA() {
  console.log('A: start');
  yield; // yield control
  console.log('A: middle');
  yield fetch('/api/data'); // yield on async
  console.log('A: done');
}

function* taskB() {
  console.log('B: start');
  yield;
  console.log('B: done');
}

scheduler.spawn(taskA);
scheduler.spawn(taskB);
// A: start → B: start → A: middle → B: done → A: done
// Interleaved execution with explicit yield points
```

