**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Chain async generators where each stage processes items from the previous. Errors propagate naturally; cleanup runs via finally blocks.

```javascript
async function* readSource(urls) {
  for (const url of urls) {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`Failed to fetch ${url}: ${res.status}`);
    yield await res.json();
  }
}

async function* validate(source) {
  for await (const item of source) {
    if (!item.id || !item.name) {
      console.warn('Skipping invalid item:', item);
      continue; // skip, don't propagate
    }
    yield item;
  }
}

async function* transform(source) {
  for await (const item of source) {
    yield {
      id: item.id,
      name: item.name.trim().toUpperCase(),
      processed: true,
    };
  }
}

async function* batchWriter(source, batchSize = 10) {
  let batch = [];
  try {
