**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Retry failed async operations up to N times; move permanently failed items to a dead letter queue for inspection.

```javascript
class RetryQueue {
  constructor({ maxAttempts = 3, backoff = 1000, onDead = console.error } = {}) {
    this.maxAttempts = maxAttempts;
    this.backoff = backoff;
    this.onDead = onDead;
    this.deadLetters = [];
  }

  async process(items, handler) {
    const results = await Promise.allSettled(
      items.map(item => this._withRetry(item, handler))
    );

    return {
      succeeded: results.filter(r => r.status === 'fulfilled').map(r => r.value),
      failed: this.deadLetters.splice(0),
    };
  }

  async _withRetry(item, handler, attempt = 1) {
    try {
      return await handler(item);
    } catch (err) {
      if (attempt >= this.maxAttempts) {
        const deadItem = { item, error: err, attempts: attempt };
        this.deadLetters.push(deadItem);
        this.onDead(deadItem);
        throw err;
      }

      const delay = this.backoff * 2 ** (attempt - 1);
      await new Promise(r => setTimeout(r, delay));
      return this._withRetry(item, handler, attempt + 1);
    }
  }
}

const queue = new RetryQueue({ maxAttempts: 3, backoff: 500 });

const { succeeded, failed } = await queue.process(
  incomingMessages,
  async (msg) => {
    await sendToAPI(msg);
  }
);

console.log(`Sent: ${succeeded.length}, Dead: ${failed.length}`);
if (failed.length > 0) await saveToDB('dead_letters', failed);
```

