The Streams API ReadableStream enables pull-based processing of streaming data — fetch response bodies, file streams, real-time feeds. Avoids buffering full response in memory.

Basic stream reading:
```javascript
async function processStream(url) {
  const response = await fetch(url);
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let accumulated = '';

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    accumulated += decoder.decode(value, { stream: true });
    // Process chunk — no need to wait for full response
    processChunk(accumulated);
  }
}
```

Modern async iteration syntax (simpler):
```javascript
async function streamLogs(url) {
  const response = await fetch(url);
  for await (const chunk of response.body) {
    const text = new TextDecoder().decode(chunk);
    appendToLog(text);
  }
}
```

With cancellation:
```javascript
async function streamWithCancel(url, signal) {
  const response = await fetch(url, { signal });
  const reader = response.body.getReader();
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      processChunk(value);
    }
  } finally {
    reader.releaseLock();
  }
}

const controller = new AbortController();
cancelBtn.onclick = () => controller.abort();
streamWithCancel('/api/stream', controller.signal);
```

Piping through transform stream:
```javascript
const { readable, writable } = new TransformStream({
  transform(chunk, controller) {
    const text = new TextDecoder().decode(chunk);
    const upper = new TextEncoder().encode(text.toUpperCase());
    controller.enqueue(upper);
  }
});

fetch('/api/data').then(r => r.body.pipeTo(writable));
const processedReader = readable.getReader();
```

Teeing (split stream for two consumers):
```javascript
const [stream1, stream2] = response.body.tee();
// stream1 and stream2 are independent copies
const reader1 = stream1.getReader(); // for logging
const reader2 = stream2.getReader(); // for processing
```

Custom readable stream:
```javascript
const countStream = new ReadableStream({
  start(controller) { this.count = 0; },
  pull(controller) {
    if (this.count < 5) {
      controller.enqueue(this.count++);
    } else {
      controller.close();
    }
  }
});
```

