      // Cleanup map entry after GC collects the value
      this.#cache.delete(key);
    });
  }

  async get(key, fetchFn) {
    const ref = this.#cache.get(key);
    if (ref) {
      const cached = ref.deref();
      if (cached !== undefined) return cached; // still alive
    }
    // Fetch fresh value
    const value = await fetchFn();
    const weakRef = new WeakRef(value);
    this.#cache.set(key, weakRef);
    this.#registry.register(value, key); // cleanup on GC
    return value;
  }
}

const cache = new AsyncWeakCache();
const data = await cache.get('users', () => fetch('/api/users').then(r => r.json()));
```

Weak DOM reference in long-running async loop:
```javascript
class LiveUpdater {
  constructor(element) {
    this.ref = new WeakRef(element);
  }

  async start() {
    while (true) {
      const el = this.ref.deref();
      if (!el) break; // element removed from DOM, stop loop
      const data = await fetchUpdate();
      el.textContent = data;
      await sleep(5000);
    }
  }
}
```

Critical warnings:
1. GC timing is non-deterministic — do NOT depend on WeakRef cleanup happening promptly
2. Within one JS job, deref() either always returns object or always returns undefined (consistent)
3. Use FinalizationRegistry for cleanup, not for observable program logic
4. Prefer Map with explicit .delete() over WeakRef when you control object lifetime

