Node.js cluster forks multiple worker processes sharing the same TCP port. Exploits multi-core CPUs since Node.js is single-threaded per process. The primary process distributes connections to workers.

```javascript
const cluster = require('cluster');
const http = require('http');
const os = require('os');

if (cluster.isPrimary) {
  const numCPUs = os.cpus().length;
  console.log(`Primary ${process.pid} running — forking ${numCPUs} workers`);

  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`Worker ${worker.process.pid} died — restarting`);
    cluster.fork(); // auto-restart dead workers
  });

} else {
  // Workers share the TCP port
  http.createServer((req, res) => {
    res.writeHead(200);
    res.end(`Worker ${process.pid} handled request\n`);
  }).listen(8000);

  console.log(`Worker ${process.pid} started`);
}
```

Graceful shutdown:
```javascript
if (cluster.isPrimary) {
  process.on('SIGTERM', () => {
    for (const worker of Object.values(cluster.workers)) {
      worker.send('shutdown');
      worker.disconnect();
    }
  });
} else {
  process.on('message', (msg) => {
    if (msg === 'shutdown') {
      server.close(() => process.exit(0));
    }
  });
}
```

Zero-downtime reload (rolling restart):
```javascript
// Primary: restart workers one at a time
let workerIds = Object.keys(cluster.workers);
async function rollingRestart() {
  for (const id of workerIds) {
    const worker = cluster.workers[id];
    worker.disconnect();
    await new Promise(r => worker.on('exit', r));
    cluster.fork();
  }
}
```

Key difference from Worker Threads: cluster uses separate processes (separate memory, full Node.js instances). Worker Threads share memory. Use cluster for CPU-bound HTTP scaling; use Worker Threads for CPU-intensive computation within one process.

