Node.js streams use pipe() and pipeline() to chain Readable → Transform → Writable without buffering full data in memory. Critical for processing large files or high-throughput data.

Basic pipe:
```javascript
const fs = require('fs');
const zlib = require('zlib');

// Compress file — never loads full file in memory
fs.createReadStream('input.log')
  .pipe(zlib.createGzip())
  .pipe(fs.createWriteStream('output.log.gz'));
```

Pipeline (preferred — handles errors and cleanup):
```javascript
const { pipeline } = require('stream/promises');

async function compressFile(input, output) {
  await pipeline(
    fs.createReadStream(input),
    zlib.createGzip(),
    fs.createWriteStream(output)
  );
  console.log('Done');
}
// pipeline() automatically destroys all streams on error
```

Custom Transform stream:
```javascript
const { Transform } = require('stream');

class CSVParser extends Transform {
  constructor() {
    super({ readableObjectMode: true }); // output objects
    this.header = null;
    this.buffer = '';
  }

  _transform(chunk, encoding, callback) {
    this.buffer += chunk.toString();
    const lines = this.buffer.split('\n');
    this.buffer = lines.pop(); // keep incomplete line
    for (const line of lines) {
      if (!this.header) {
        this.header = line.split(',');
      } else {
        const obj = Object.fromEntries(
          this.header.map((h, i) => [h, line.split(',')[i]])
        );
        this.push(obj);
      }
    }
    callback();
  }

  _flush(callback) {
    if (this.buffer) this.push(this.buffer);
    callback();
  }
}

await pipeline(
  fs.createReadStream('data.csv'),
  new CSVParser(),
  new WritableStream({ write(obj) { db.insert(obj); } })
);
```

Backpressure: if consumer is slower than producer, pipe() pauses the source automatically. Never push data faster than consumer can handle — use highWaterMark to tune buffer size.

