Modifying shared state before awaiting and after resuming creates windows where other async tasks observe inconsistent state. Classic async race condition.

Bug — shared counter corrupted:
```javascript
let counter = 0;

async function increment() {
  const current = counter; // read
  await doSomethingAsync(); // yield — another call can run here!
  counter = current + 1;   // write stale value — lost update
}

// Two concurrent calls — both read counter=0, both write 1 — net result: 1 (not 2)
await Promise.all([increment(), increment()]);
console.log(counter); // 1, expected 2
```

Bug — shared object corrupted mid-operation:
```javascript
const state = { status: 'idle', data: null };

async function loadData() {
  state.status = 'loading';
  const data = await fetch('/api').then(r => r.json());
  // Another loadData() call ran during await — state.status is unpredictable
  state.status = 'done';
  state.data = data; // may overwrite newer data
}

loadData();
loadData(); // concurrent — race condition on state
```

Fix — mutex/queue for shared state:
```javascript
const mutex = new Mutex();

async function safeIncrement() {
  await mutex.acquire();
  try {
    counter++;
  } finally {
    mutex.release();
  }
}

// Or queue-based: process one at a time
const queue = new AsyncQueue();
async function queuedIncrement() {
  await queue.enqueue(async () => {
    counter++;
  });
}
```

Fix — immutable state transitions:
```javascript
let state = { status: 'idle', data: null };

async function loadData() {
  // Snapshot state — each call works with local copy
  const prevState = state;
  if (prevState.status === 'loading') return; // guard
  state = { ...prevState, status: 'loading' }; // atomic replace
  try {
    const data = await fetch('/api').then(r => r.json());
    state = { status: 'done', data };
  } catch {
    state = { ...state, status: 'error' };
  }
}
```

