**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Error boundaries in async code isolate failures so one failing operation does not cascade to unrelated operations. Critical for resilient concurrent systems.

Basic error boundary wrapper:
```javascript
async function withErrorBoundary(name, fn) {
  try {
    return { ok: true, value: await fn() };
  } catch (err) {
    console.error(`[${name}] failed:`, err.message);
    return { ok: false, error: err };
  }
}

// All three run — one failure doesn't stop others
const [user, posts, settings] = await Promise.all([
  withErrorBoundary('fetchUser', () => fetchUser(id)),
  withErrorBoundary('fetchPosts', () => fetchPosts(id)),
  withErrorBoundary('fetchSettings', () => fetchSettings(id)),
]);

if (user.ok) renderUser(user.value);
if (posts.ok) renderPosts(posts.value);
if (settings.ok) applySettings(settings.value);
// Partial success — show what we have
```

Fallback values:
```javascript
async function withFallback(fn, fallback) {
  try {
    return await fn();
  } catch {
    return fallback;
  }
}

const [primaryData, backupData] = await Promise.all([
  withFallback(fetchPrimary, null),
  withFallback(fetchBackup, null),
]);
const data = primaryData ?? backupData ?? defaultData;
```

Timeout boundary:
```javascript
async function withTimeout(fn, ms, fallback = null) {
  const timeoutSignal = AbortSignal.timeout(ms);
  try {
    return await fn(timeoutSignal);
  } catch (err) {
    if (err.name === 'TimeoutError') {
      console.warn(`Operation timed out after ${ms}ms`);
      return fallback;
    }
    throw err; // re-throw non-timeout errors
  }
}
```

Retry boundary:
```javascript
async function withRetry(fn, retries = 3, backoffMs = 1000) {
  for (let i = 0; i <= retries; i++) {
    try {
      return await fn();
    } catch (err) {
      if (i === retries) throw err;
      if (err.name === 'AbortError') throw err; // never retry cancellation
      await new Promise(r => setTimeout(r, backoffMs * 2 ** i));
    }
  }
}
```

