**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Lazy evaluation defers computation until results are actually needed. Combined with memoization, expensive async operations run at most once regardless of concurrent requests.

Lazy async value (compute once, reuse everywhere):
```javascript
function lazyAsync(fn) {
  let promise = null;
  return () => {
    if (!promise) promise = fn();
    return promise;
  };
}

const getConfig = lazyAsync(async () => {
  const res = await fetch('/api/config');
  return res.json();
});

// All three calls share one fetch — no duplicate requests
const [c1, c2, c3] = await Promise.all([
  getConfig(),
  getConfig(),
  getConfig()
]);
```

Memoization with TTL:
```javascript
function memoizeAsync(fn, ttlMs = 60000) {
  const cache = new Map();

  return async function(...args) {
    const key = JSON.stringify(args);
    const cached = cache.get(key);
    if (cached && Date.now() - cached.timestamp < ttlMs) {
      return cached.value;
    }
    const value = await fn(...args);
    cache.set(key, { value, timestamp: Date.now() });
    return value;
  };
}

const cachedUser = memoizeAsync(fetchUser, 30000);
await cachedUser(123); // network call
await cachedUser(123); // cache hit
await cachedUser(456); // network call — different key
```

Dedup in-flight requests (request coalescing):
```javascript
const inflight = new Map();

async function dedupFetch(url) {
  if (inflight.has(url)) {
    return inflight.get(url); // join existing request
  }
  const promise = fetch(url).then(r => r.json()).finally(() => {
    inflight.delete(url); // cleanup after settle
  });
  inflight.set(url, promise);
  return promise;
}

// 10 concurrent calls to same URL = 1 network request
await Promise.all(Array.from({ length: 10 }, () => dedupFetch('/api/users')));
```

