AsyncGenerator objects are returned by async function* declarations. They implement both async iterable and async iterator protocols — can be used with for-await-of or consumed manually.

Basic async generator:
```javascript
async function* numberStream(start, end, delayMs) {
  for (let i = start; i <= end; i++) {
    await new Promise(r => setTimeout(r, delayMs));
    yield i;
  }
}

for await (const num of numberStream(1, 5, 500)) {
  console.log(num); // 1, 2, 3, 4, 5 — each after 500ms
}
```

Infinite async stream with cleanup:
```javascript
async function* eventStream(source) {
  try {
    while (true) {
      const event = await source.nextEvent();
      yield event;
    }
  } finally {
    source.close(); // cleanup when generator is done/cancelled
  }
}

const stream = eventStream(dataSource);
const { value: first } = await stream.next();
await stream.return(); // triggers finally — closes source
```

Manual iteration for control:
```javascript
async function* paginate(url) {
  let nextUrl = url;
  while (nextUrl) {
    const res = await fetch(nextUrl);
    const { data, next } = await res.json();
    yield* data; // yield each item
    nextUrl = next;
  }
}

const gen = paginate('/api/items');
const { value: first } = await gen.next();
const { value: second } = await gen.next();
await gen.return(); // stop early — skips remaining pages
```

Error injection via throw():
```javascript
async function* retryable() {
  while (true) {
    try {
      yield await fetchData();
    } catch (err) {
      console.log('Retrying after error:', err);
      // generator continues — next next() call tries again
    }
  }
}

const gen = retryable();
await gen.next(); // get data
await gen.throw(new Error('force retry')); // inject error — generator handles it
```

Pipeline of async generators:
```javascript
async function* filter(source, predicate) {
  for await (const item of source) {
    if (predicate(item)) yield item;
  }
}

async function* map(source, transform) {
  for await (const item of source) {
    yield transform(item);
  }
}

const pipeline = filter(map(numberStream(1, 100, 0), x => x * 2), x => x % 6 === 0);
for await (const val of pipeline) console.log(val); // 6, 12, 18...
```

