performance.now() returns a DOMHighResTimeStamp — monotonic, microsecond-precision clock unaffected by system clock changes. Ideal for measuring async operation durations.

Basic timing:
```javascript
const t0 = performance.now();
await heavyOperation();
const t1 = performance.now();
console.log(`Operation took ${(t1 - t0).toFixed(2)}ms`);
```

Benchmarking concurrent vs sequential:
```javascript
async function benchmark() {
  const items = Array.from({ length: 10 }, (_, i) => i);

  // Sequential
  const seqStart = performance.now();
  for (const item of items) {
    await fetchItem(item);
  }
  const seqTime = performance.now() - seqStart;

  // Parallel
  const parStart = performance.now();
  await Promise.all(items.map(fetchItem));
  const parTime = performance.now() - parStart;

  console.log(`Sequential: ${seqTime.toFixed(0)}ms`);
  console.log(`Parallel: ${parTime.toFixed(0)}ms`);
  console.log(`Speedup: ${(seqTime / parTime).toFixed(1)}x`);
}
```

Measure event loop lag:
```javascript
function measureEventLoopLag() {
  const expected = performance.now();
  setTimeout(() => {
    const actual = performance.now();
    const lag = actual - expected;
    console.log(`Event loop lag: ${lag.toFixed(2)}ms`);
  }, 0);
}
```

Performance marks for async spans:
```javascript
async function tracedFetch(url) {
  performance.mark('fetch-start');
  const response = await fetch(url);
  performance.mark('fetch-end');
  performance.measure('fetch-duration', 'fetch-start', 'fetch-end');
  const [measure] = performance.getEntriesByName('fetch-duration');
  console.log(`Fetch took ${measure.duration.toFixed(2)}ms`);
  return response;
}
```

Precision note: In cross-origin isolated contexts (COOP+COEP headers set), precision is ~5 microseconds. Otherwise ~100 microseconds (browser-imposed for timing attack mitigation).

