Cache stampede (thundering herd) occurs when many concurrent requests find a cold cache simultaneously, all triggering upstream fetches instead of sharing one result.

Bug — naive cache with stampede:
```javascript
const cache = new Map();

async function getData(key) {
  if (cache.has(key)) return cache.get(key); // cache hit

  // All concurrent calls reach here simultaneously — all fetch!
  const data = await fetchFromDB(key);
  cache.set(key, data);
  return data;
}

// 100 concurrent requests for same key = 100 DB queries
await Promise.all(Array.from({ length: 100 }, () => getData('users')));
```

Fix — promise coalescing (store promise in cache, not just value):
```javascript
const promiseCache = new Map();

async function getDataSafe(key) {
  if (promiseCache.has(key)) {
    return promiseCache.get(key); // return SAME promise — all share one fetch
  }

  const promise = fetchFromDB(key).then(data => {
    // Replace promise with value after resolution
    promiseCache.set(key, Promise.resolve(data));
    return data;
  }).catch(err => {
    promiseCache.delete(key); // on error — remove so next request retries
    throw err;
  });

  promiseCache.set(key, promise);
  return promise;
}

// 100 concurrent requests = 1 DB query — all await the same promise
await Promise.all(Array.from({ length: 100 }, () => getDataSafe('users')));
```

With TTL:
```javascript
const cache = new Map();

async function cachedFetch(key, ttlMs = 60000) {
  const entry = cache.get(key);
  if (entry && Date.now() - entry.createdAt < ttlMs) {
    return entry.promise; // reuse in-flight or settled promise
  }
  const promise = fetchFromDB(key);
  cache.set(key, { promise, createdAt: Date.now() });
  return promise;
}
```

