**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Creating Workers per task is expensive (spawn overhead, memory). A pool maintains N workers, queues tasks, and dispatches to idle workers for efficient CPU parallelism.

```javascript
class WorkerPool {
  #workers = [];
  #queue = [];
  #size;

  constructor(workerScript, size = navigator.hardwareConcurrency ?? 4) {
    this.#size = size;
    for (let i = 0; i < size; i++) {
      this.#addWorker(workerScript);
    }
  }

  #addWorker(script) {
    const worker = new Worker(script);
    worker.idle = true;
    worker.addEventListener('message', (e) => {
      worker.currentResolve(e.data);
      worker.idle = true;
      this.#dispatch();
    });
    worker.addEventListener('error', (e) => {
      worker.currentReject(e);
      worker.idle = true;
      this.#dispatch();
    });
    this.#workers.push(worker);
  }

  #dispatch() {
    if (!this.#queue.length) return;
    const worker = this.#workers.find(w => w.idle);
    if (!worker) return;

    const { task, resolve, reject } = this.#queue.shift();
    worker.idle = false;
    worker.currentResolve = resolve;
    worker.currentReject = reject;
    worker.postMessage(task);
  }

  run(task) {
    return new Promise((resolve, reject) => {
      this.#queue.push({ task, resolve, reject });
      this.#dispatch();
    });
  }

  terminate() {
    this.#workers.forEach(w => w.terminate());
  }
}

// Usage
const pool = new WorkerPool('compute-worker.js', 4);
const results = await Promise.all(
  Array.from({ length: 20 }, (_, i) => pool.run({ n: i }))
);
pool.terminate();
```

Pool sizing: `navigator.hardwareConcurrency` gives logical CPU count. For I/O-bound workers use 2-4x CPUs; for CPU-bound use exact CPU count.

