**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

The async iterator protocol requires an object with a next() method returning Promise<{value, done}>. Implementing it manually enables full control over push-based async data sources.

Manual async iterator:
```javascript
function createAsyncIterator(source) {
  return {
    [Symbol.asyncIterator]() { return this; },

    async next() {
      const value = await source.pull();
      if (value === null) return { value: undefined, done: true };
      return { value, done: false };
    },

    async return(value) {
      await source.cleanup();
      return { value, done: true };
    },

    async throw(err) {
      await source.cleanup();
      throw err;
    }
  };
}
```

EventEmitter as async iterator:
```javascript
function asyncFromEmitter(emitter, dataEvent, endEvent, errorEvent) {
  const buffer = [];
  const waiters = [];
  let done = false;
  let error = null;

  emitter.on(dataEvent, (data) => {
    if (waiters.length) waiters.shift()({ value: data, done: false });
    else buffer.push(data);
  });

  emitter.on(endEvent, () => {
    done = true;
    waiters.forEach(r => r({ value: undefined, done: true }));
    waiters.length = 0;
  });

  emitter.on(errorEvent, (err) => {
    error = err;
    waiters.forEach(r => r(Promise.reject(err)));
  });

  return {
    [Symbol.asyncIterator]() { return this; },
    next() {
      if (buffer.length) return Promise.resolve({ value: buffer.shift(), done: false });
      if (done) return Promise.resolve({ value: undefined, done: true });
      if (error) return Promise.reject(error);
      return new Promise(r => waiters.push(r));
    }
  };
}

// Usage
const iter = asyncFromEmitter(emitter, 'data', 'end', 'error');
for await (const chunk of iter) processChunk(chunk);
```

