**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Processing a large list of items concurrently — but throttled to N concurrent operations — prevents overwhelming downstream APIs or databases while still running faster than pure sequential.

Simple concurrency limiter:
```javascript
async function processWithConcurrency(items, concurrency, processor) {
  const results = [];
  const executing = [];

  for (const item of items) {
    const p = processor(item).then(result => {
      results.push(result);
      executing.splice(executing.indexOf(p), 1);
    });
    executing.push(p);

    if (executing.length >= concurrency) {
      await Promise.race(executing); // wait for one to finish before adding
    }
  }

  await Promise.all(executing); // wait for remaining
  return results;
}

// Process 1000 URLs, max 5 concurrent
await processWithConcurrency(urls, 5, async (url) => {
  const res = await fetch(url);
  return res.json();
});
```

Semaphore-based approach (cleaner):
```javascript
class AsyncSemaphore {
  #permits;
  #queue = [];

  constructor(permits) {
    this.#permits = permits;
  }

  async acquire() {
    if (this.#permits > 0) {
      this.#permits--;
      return;
    }
    await new Promise(r => this.#queue.push(r));
    this.#permits--;
  }

  release() {
    this.#permits++;
    if (this.#queue.length) this.#queue.shift()();
  }
}

const sem = new AsyncSemaphore(5);
await Promise.all(urls.map(async (url) => {
  await sem.acquire();
  try {
    return await fetch(url).then(r => r.json());
  } finally {
    sem.release();
  }
}));
```

With progress tracking:
```javascript
async function batchProcess(items, concurrency, processor, onProgress) {
  let completed = 0;
  const sem = new AsyncSemaphore(concurrency);
  return Promise.all(items.map(async (item) => {
    await sem.acquire();
    try {
      const result = await processor(item);
      onProgress(++completed, items.length);
      return result;
    } finally {
      sem.release();
    }
  }));
}
```

