**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

IndexedDB transactions auto-commit when no more requests are pending. If an await yields control before all requests complete, the transaction commits prematurely.

Bug — transaction commits during await:
```javascript
async function buggyTransaction(db) {
  const tx = db.transaction('store', 'readwrite');
  const store = tx.objectStore('store');

  const item = await new Promise(r => store.get('key').onsuccess = e => r(e.target.result));

  // Transaction has AUTO-COMMITTED here — the get() request completed,
  // no more pending requests, transaction done

  await processItem(item); // this await makes it worse — more time passes

  // This put() fails — transaction already committed!
  store.put(modified, 'key'); // throws InvalidStateError
}
```

Fix — keep all requests within the transaction synchronously:
```javascript
async function safeTransaction(db) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction('store', 'readwrite');
    const store = tx.objectStore('store');

    // Queue all requests synchronously — no await between them
    const getReq = store.get('key');

    getReq.onsuccess = (e) => {
      const item = e.target.result;
      const modified = processItemSync(item); // synchronous processing
      store.put(modified, 'key'); // still within same transaction
    };

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}
```

Fix — use structured async with complete transaction wrapper:
```javascript
function withTransaction(db, stores, mode, callback) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(stores, mode);
    callback(tx); // callback must queue all IDB requests synchronously
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error);
  });
}

await withTransaction(db, ['store'], 'readwrite', (tx) => {
  const store = tx.objectStore('store');
  const req = store.get('key');
  req.onsuccess = () => store.put(process(req.result), 'key');
});
```

