AsyncLocalStorage (Node.js 12.17+) propagates context across async boundaries — request IDs, user sessions, tracing spans — without passing them explicitly through every function call.

Basic request context:
```javascript
const { AsyncLocalStorage } = require('async_hooks');

const requestContext = new AsyncLocalStorage();

// Middleware sets context for request lifetime
app.use((req, res, next) => {
  const ctx = {
    requestId: crypto.randomUUID(),
    userId: req.user?.id,
    startTime: Date.now()
  };
  requestContext.run(ctx, next); // all async work in next() inherits ctx
});

// Any function — no ctx argument needed
async function queryDB(sql) {
  const ctx = requestContext.getStore(); // auto-available
  logger.info({ requestId: ctx.requestId, sql });
  return db.query(sql);
}

async function sendEmail(to, body) {
  const ctx = requestContext.getStore();
  logger.info({ requestId: ctx.requestId, to });
  return mailer.send(to, body);
}

// Controller — no threading of ctx required
app.get('/profile', async (req, res) => {
  const [user, posts] = await Promise.all([
    queryDB('SELECT * FROM users WHERE id = $1', [req.user.id]),
    queryDB('SELECT * FROM posts WHERE user_id = $1', [req.user.id]),
  ]);
  res.json({ user, posts });
});
```

Distributed tracing:
```javascript
const traceContext = new AsyncLocalStorage();

function startSpan(name) {
  const parent = traceContext.getStore();
  const span = tracer.startSpan(name, { parent });
  return traceContext.run(span, () => span);
}

async function withSpan(name, fn) {
  const span = startSpan(name);
  try {
    return await traceContext.run(span, fn);
  } finally {
    span.finish();
  }
}
```

Note: AsyncLocalStorage uses Node.js async_hooks internally. Slight performance overhead — benchmark for hot paths.

