Wrapping an already-promise-returning function in new Promise() is redundant, hides errors, and causes issues. Known as the explicit Promise construction anti-pattern.

Bad — unnecessary wrapping:
```javascript
// fetch() already returns a Promise — no need to wrap!
function badFetch(url) {
  return new Promise((resolve, reject) => {
    fetch(url)
      .then(response => resolve(response)) // pointless
      .catch(err => reject(err));           // pointless
  });
}

// Even worse — swallows errors silently
function veryBad(url) {
  return new Promise((resolve, reject) => {
    fetch(url).then(r => {
      const json = r.json(); // if this throws, it's UNCAUGHT inside new Promise
      resolve(json);
    });
    // No .catch — network errors swallowed
  });
}
```

Good — use the promise directly:
```javascript
function goodFetch(url) {
  return fetch(url); // just return it
}

// Or with transformation:
function fetchJson(url) {
  return fetch(url).then(r => r.json());
}

// async/await version:
async function fetchJson(url) {
  const r = await fetch(url);
  return r.json();
}
```

When new Promise() IS correct — wrapping callback-only APIs:
```javascript
// Good — only wrap non-promise APIs
function readFile(path) {
  return new Promise((resolve, reject) => {
    fs.readFile(path, 'utf8', (err, data) => {
      if (err) reject(err);
      else resolve(data);
    });
  });
}

// Or use built-in util.promisify for Node.js callbacks:
const { promisify } = require('util');
const readFileAsync = promisify(fs.readFile);
```

Rule: only use new Promise() when consuming a callback-based API. If the function already returns a Promise, chain it directly.

