**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Combining async generators with push-based sources creates observable-like reactive streams without requiring RxJS. Useful for real-time updates, live search, sensor data.

Push-to-pull adapter (reactive source to async iterator):
```javascript
function fromEvent(target, event) {
  const { promise: nextEvent, resolve } = Promise.withResolvers();
  let currentResolver = resolve;
  let buffer = [];

  target.addEventListener(event, (e) => {
    if (currentResolver) {
      const r = currentResolver;
      currentResolver = null;
      r({ value: e, done: false });
    } else {
      buffer.push(e);
    }
  });

  return {
    [Symbol.asyncIterator]() { return this; },
    next() {
      if (buffer.length) return Promise.resolve({ value: buffer.shift(), done: false });
      const { promise, resolve: r } = Promise.withResolvers();
      currentResolver = r;
      return promise;
    },
    return() {
      target.removeEventListener(event, handler);
      return Promise.resolve({ done: true });
    }
  };
}

// Live search stream
const inputEvents = fromEvent(searchInput, 'input');
for await (const event of inputEvents) {
  const query = event.target.value;
  const results = await fetchSearch(query);
  renderResults(results);
}
```

Operators (map/filter/debounce) for async iterables:
```javascript
async function* map(source, fn) {
  for await (const item of source) yield fn(item);
}

async function* filter(source, pred) {
  for await (const item of source) if (pred(item)) yield item;
}

async function* debounce(source, ms) {
  let lastTimer;
  for await (const item of source) {
    clearTimeout(lastTimer);
    await new Promise(r => { lastTimer = setTimeout(r, ms); });
    yield item;
  }
}

// Pipeline: filter empty queries, debounce 300ms, map to search
const pipeline = map(
  debounce(
    filter(fromEvent(input, 'input'), e => e.target.value.length > 2),
    300
  ),
  e => e.target.value
);

for await (const query of pipeline) {
  renderResults(await fetchSearch(query));
}
```

