Promise.resolve().then(() => console.log('C')); // microtask — runs before macrotask
console.log('B'); // 2
// Output: A, B, C, D
// Microtask (C) before macrotask (D) even though both queued before B completes
```

All microtasks drain before next macrotask:
```javascript
setTimeout(() => console.log('macrotask'), 0);

Promise.resolve()
  .then(() => { console.log('micro 1'); return Promise.resolve(); })
  .then(() => console.log('micro 2'))
  .then(() => console.log('micro 3'));
// Output: micro 1, micro 2, micro 3, macrotask
// ALL microtasks complete before macrotask runs
```

Nested setTimeout minimum delay (4ms after 5 levels):
```javascript
function runNested(depth, callback) {
  if (depth === 0) return callback();
  setTimeout(() => runNested(depth - 1, callback), 0);
}
// Depth 1-4: near-0ms. Depth 5+: min 4ms each
// Don't rely on setTimeout(fn, 0) for precise timing
```

Common anti-pattern — setTimeout for ordering:
```javascript
// BAD: using setTimeout to "wait" for DOM update
button.click();
setTimeout(() => checkDOMState(), 0); // fragile — may run before or after update

// GOOD: use requestAnimationFrame or Promise
await new Promise(r => requestAnimationFrame(r));
checkDOMState(); // guaranteed after next render
```

SetTimeout vs setInterval vs queueMicrotask:
- queueMicrotask: before next macrotask, no delay
- setTimeout(fn, 0): first available macrotask slot, min ~1ms (or 4ms nested)
- setInterval(fn, n): every n ms (minimum), may drift under load

**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

The lost update problem: two concurrent async operations both read a value, both compute a new value, both write — one write is lost because it overwrites the other.

Classic lost update:
```javascript
let balance = 100;

async function deduct(amount) {
  const current = balance;    // read
  await processPayment(amount); // yield — another deduct can run here!
  balance = current - amount; // write — may overwrite concurrent write
}

// Two concurrent deductions of 30
await Promise.all([deduct(30), deduct(30)]);
console.log(balance); // Should be 40, but likely 70 — one update lost
```

Fix — atomic compare-and-swap pattern:
```javascript
async function safeDeduct(amount) {
  while (true) {
    const current = balance;
    await processPayment(amount);
    // Only write if balance hasn't changed since we read
    if (balance === current) {
      balance = current - amount;
      return;
    }
    // Conflict — retry
    console.log('Conflict — retrying');
  }
}
```

Fix — sequential queue (serialized updates):
```javascript
const updateQueue = new AsyncQueue();

async function queuedDeduct(amount) {
  return updateQueue.enqueue(async () => {
    await processPayment(amount);
    balance -= amount; // safe — only one runs at a time
  });
}
```

Fix — optimistic locking with version:
```javascript
let balance = 100;
let version = 0;

async function deductWithVersion(amount) {
  const readVersion = version;
  const current = balance;
  await processPayment(amount);
  if (version !== readVersion) throw new Error('Concurrent modification — retry');
  balance = current - amount;
  version++;
}
```

Fix — move mutable state to server (authoritative):
```javascript
async function serverDeduct(userId, amount) {
  // Server handles atomicity — client just sends intent
  const result = await api.post('/payments/deduct', { userId, amount });
  return result.newBalance; // server returns canonical value
}
```

