The using and await using declarations (TC39 explicit resource management proposal) automatically call dispose/asyncDispose when scope exits — async equivalent of try/finally for resource cleanup.

Basic await using:
```javascript
class DatabaseConnection {
  async query(sql) { /* ... */ }

  async [Symbol.asyncDispose]() {
    await this.close(); // called automatically when scope exits
  }
}

async function doWork() {
  await using conn = await openConnection();
  const data = await conn.query('SELECT * FROM users');
  return data;
  // conn[Symbol.asyncDispose]() called here — even if exception thrown
}
```

Sync version for non-async resources:
```javascript
class FileHandle {
  [Symbol.dispose]() {
    this.fd.closeSync();
  }
}

function readFile(path) {
  using handle = openFileSync(path);
  return handle.readAllText();
  // handle[Symbol.dispose]() called here
}
```

Multiple resources — all disposed in reverse order:
```javascript
async function transaction() {
  await using db = await openDB();
  await using tx = await db.beginTransaction();
  await using lock = await acquireLock('resource');

  await tx.execute('UPDATE ...');
  await tx.commit();
  // lock disposed first, then tx, then db (reverse order)
}
```

Disposable stack for dynamic cleanup:
```javascript
async function processMultiple(items) {
  await using stack = new AsyncDisposableStack();
  const connections = await Promise.all(
    items.map(async (item) => {
      const conn = await openConnection(item.url);
      stack.use(conn); // register for auto-cleanup
      return conn;
    })
  );
  await Promise.all(connections.map(c => c.process()));
  // All connections disposed on exit
}
```

Note: requires TypeScript 5.2+ or Babel transform. Runtime support varies — check target environment.

