async function processMultiple(items) {
  await using stack = new AsyncDisposableStack();
  const connections = await Promise.all(
    items.map(async (item) => {
      const conn = await openConnection(item.url);
      stack.use(conn); // register for auto-cleanup
      return conn;
    })
  );
  await Promise.all(connections.map(c => c.process()));
  // All connections disposed on exit
}
