**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

When an access token expires, multiple concurrent requests may all detect the 401 and try to refresh simultaneously — causing multiple refresh calls and potential token invalidation.

Bug — N concurrent refreshes:
```javascript
let token = null;

async function apiRequest(url) {
  let res = await fetch(url, { headers: { Authorization: `Bearer ${token}` }});
  if (res.status === 401) {
    // All concurrent requests see 401 and all try to refresh!
    token = await refreshToken();
    res = await fetch(url, { headers: { Authorization: `Bearer ${token}` }});
  }
  return res.json();
}

// 5 concurrent requests — all expire — 5 refresh calls — server may invalidate all
await Promise.all([apiRequest('/a'), apiRequest('/b'), apiRequest('/c')]);
```

Fix — singleton refresh promise:
```javascript
let token = null;
let refreshPromise = null;

async function getValidToken() {
  if (token && !isExpired(token)) return token;

  if (!refreshPromise) {
    refreshPromise = refreshToken().then(newToken => {
      token = newToken;
      refreshPromise = null; // clear after done
      return newToken;
    }).catch(err => {
      refreshPromise = null; // clear on error — allow retry
      throw err;
    });
  }

  return refreshPromise; // all concurrent callers await same promise
}

async function apiRequest(url) {
  const validToken = await getValidToken();
  const res = await fetch(url, { headers: { Authorization: `Bearer ${validToken}` }});
  if (res.status === 401) {
    token = null; // invalidate cached token
    const newToken = await getValidToken(); // triggers one fresh refresh
    return fetch(url, { headers: { Authorization: `Bearer ${newToken}` }}).then(r => r.json());
  }
  return res.json();
}
```

