EventEmitter pattern for async workflows — decouple producers and consumers, allow multiple listeners, and support async handler chains.

Async-capable EventEmitter:
```javascript
class AsyncEventEmitter {
  #handlers = new Map();

  on(event, handler) {
    if (!this.#handlers.has(event)) this.#handlers.set(event, []);
    this.#handlers.get(event).push(handler);
    return () => this.off(event, handler); // return unsubscribe function
  }

  off(event, handler) {
    const handlers = this.#handlers.get(event);
    if (handlers) {
      const idx = handlers.indexOf(handler);
      if (idx !== -1) handlers.splice(idx, 1);
    }
  }

  once(event, handler) {
    const wrapper = async (...args) => {
      this.off(event, wrapper);
      return handler(...args);
    };
    this.on(event, wrapper);
  }

  async emit(event, ...args) {
    const handlers = this.#handlers.get(event) ?? [];
    // Run all handlers — await each in sequence or use Promise.all for parallel
    await Promise.all(handlers.map(h => h(...args)));
  }
}

const emitter = new AsyncEventEmitter();

const unsub = emitter.on('data', async (chunk) => {
  await processChunk(chunk);
  renderUpdate(chunk);
});

const done = new Promise(resolve => emitter.once('end', resolve));
await emitter.emit('data', chunk1);
await emitter.emit('end', { total: 100 });
await done;
unsub(); // remove listener
```

Typed events with TypeScript-style pattern:
```javascript
const bus = new AsyncEventEmitter();

// Separate listener sets per event type
bus.on('user:login', async ({ userId }) => logAnalytics('login', userId));
bus.on('user:login', async ({ userId }) => updateLastSeen(userId));

// Emit triggers all login handlers concurrently
await bus.emit('user:login', { userId: '123' });
```

