Fan-out distributes one task into many parallel subtasks. Fan-in collects results back into one. Core pattern for parallel data processing pipelines.

Basic fan-out/fan-in:
```javascript
async function fanOutFanIn(items, processor, concurrency = Infinity) {
  if (concurrency === Infinity) {
    // Full parallel fan-out
    return Promise.all(items.map(processor));
  }

  // Bounded fan-out via semaphore
  const sem = new AsyncSemaphore(concurrency);
  return Promise.all(items.map(async (item) => {
    await sem.acquire();
    try {
      return await processor(item);
    } finally {
      sem.release();
    }
  }));
}

// Fan out to 10 workers, fan in to single result array
const urls = Array.from({ length: 100 }, (_, i) => `/api/item/${i}`);
const results = await fanOutFanIn(urls, fetchJson, 10);
```

Map-reduce pipeline:
```javascript
async function mapReduce(items, mapper, reducer, initial) {
  // Fan-out: map phase (parallel)
  const mapped = await Promise.all(items.map(mapper));

  // Fan-in: reduce phase (sequential, or parallel with a tree reduction)
  return mapped.reduce(reducer, initial);
}

const totalWordCount = await mapReduce(
  documentUrls,
  async (url) => {
    const text = await fetch(url).then(r => r.text());
    return text.split(/\s+/).length;
  },
  (sum, count) => sum + count,
  0
);
```

Streaming fan-in (process as results arrive):
```javascript
async function* fanInOrdered(promises) {
  // Yield results in order they resolve (not input order)
  const indexed = promises.map((p, i) => p.then(v => ({ i, v })));
  while (indexed.length) {
    const { i, v } = await Promise.race(indexed);
    indexed.splice(i, 1);
    yield v;
  }
}

for await (const result of fanInOrdered(tasks.map(t => t()))) {
  displayResult(result); // display as each finishes
}
```

