Middleware pipeline chains async functions where each calls next() to pass control. Used in Express, Koa, and custom request processing chains.

Koa-style async middleware:
```javascript
class AsyncPipeline {
  #middlewares = [];

  use(fn) {
    this.#middlewares.push(fn);
    return this;
  }

  async run(ctx) {
    let index = -1;

    const dispatch = async (i) => {
      if (i <= index) throw new Error('next() called multiple times');
      index = i;
      const fn = this.#middlewares[i];
      if (!fn) return; // end of chain
      await fn(ctx, () => dispatch(i + 1));
    };

    await dispatch(0);
    return ctx;
  }
}

// Usage
const pipeline = new AsyncPipeline();

pipeline.use(async (ctx, next) => {
  ctx.startTime = Date.now();
  await next();
  ctx.duration = Date.now() - ctx.startTime;
  console.log(`Request took ${ctx.duration}ms`);
});

pipeline.use(async (ctx, next) => {
  if (!ctx.token) throw new Error('Unauthorized');
  ctx.user = await verifyToken(ctx.token);
  await next();
});

pipeline.use(async (ctx, next) => {
  ctx.result = await processRequest(ctx);
  await next();
});

const ctx = { token: 'abc123', data: payload };
await pipeline.run(ctx);
console.log(ctx.result, ctx.duration);
```

Error handling middleware:
```javascript
pipeline.use(async (ctx, next) => {
  try {
    await next();
  } catch (err) {
    ctx.error = err;
    ctx.status = err.status || 500;
    ctx.body = { error: err.message };
  }
});
// Always register error handler FIRST — it wraps all subsequent middleware
```

