**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Circuit breaker prevents cascading failures — if a service repeatedly fails, stop calling it temporarily and return a fast fallback. Three states: Closed (normal), Open (failing, return error immediately), Half-Open (test if recovered).

```javascript
class CircuitBreaker {
  #state = 'closed'; // 'closed' | 'open' | 'half-open'
  #failureCount = 0;
  #lastFailure = null;
  #threshold;
  #timeout;

  constructor(threshold = 5, timeoutMs = 30000) {
    this.#threshold = threshold;
    this.#timeout = timeoutMs;
  }

  async call(fn) {
    if (this.#state === 'open') {
      if (Date.now() - this.#lastFailure > this.#timeout) {
        this.#state = 'half-open'; // try again
      } else {
        throw new Error('Circuit breaker OPEN — service unavailable');
      }
    }

    try {
      const result = await fn();
      this.#onSuccess();
      return result;
    } catch (err) {
      this.#onFailure();
      throw err;
    }
  }

  #onSuccess() {
    this.#failureCount = 0;
    this.#state = 'closed';
  }

  #onFailure() {
    this.#failureCount++;
    this.#lastFailure = Date.now();
    if (this.#failureCount >= this.#threshold) {
      this.#state = 'open';
      console.warn('Circuit breaker opened — too many failures');
    }
  }

  get state() { return this.#state; }
}

const breaker = new CircuitBreaker(5, 30000);

async function callExternalAPI(data) {
  return breaker.call(async () => {
    const res = await fetch('/api/external', { method: 'POST', body: JSON.stringify(data) });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  });
}

// Falls back immediately if circuit open:
try {
  return await callExternalAPI(data);
} catch (err) {
  if (err.message.includes('Circuit breaker OPEN')) {
    return getCachedOrDefaultResponse();
  }
  throw err;
}
```

