Backpressure prevents fast producers from overwhelming slow consumers. When the consumer's buffer is full, the producer pauses — fundamental for memory-safe streaming.

Manual backpressure with AsyncGenerator:
```javascript
async function* producer(items) {
  for (const item of items) {
    yield item; // pauses here until consumer calls next()
  }
}

async function consumer(source, processItem) {
  for await (const item of source) {
    await processItem(item); // consumer controls pace — generator waits
  }
}

// Producer only advances when consumer is ready
await consumer(producer(largeDataset), async (item) => {
  await slowDBWrite(item); // consumer may be slower — producer pauses
});
```

Bounded async queue with backpressure:
```javascript
class BoundedQueue {
  #items = [];
  #maxSize;
  #consumers = [];
  #producers = [];

  constructor(maxSize) { this.#maxSize = maxSize; }

  async enqueue(item) {
    if (this.#items.length < this.#maxSize) {
      this.#items.push(item);
      this.#consumers.shift()?.(); // wake waiting consumer
    } else {
      // Queue full — producer blocks until consumer takes item
      await new Promise(r => this.#producers.push(r));
      this.#items.push(item);
    }
  }

  async dequeue() {
    if (this.#items.length > 0) {
      const item = this.#items.shift();
      this.#producers.shift()?.(); // wake waiting producer
      return item;
    }
    return new Promise(r => this.#consumers.push(
      () => r(this.#items.shift())
    ));
  }
}

const queue = new BoundedQueue(10); // max 10 items buffered

// Producer fills queue — pauses when full
const produce = async () => {
  for (const item of dataSource) await queue.enqueue(item);
};

// Consumer drains queue — producer unblocks as space opens
const consume = async () => {
  while (true) {
    const item = await queue.dequeue();
    await processSlowly(item);
  }
};

await Promise.all([produce(), consume()]);
```

