Bounded async queue with backpressure:
```javascript
class BoundedQueue {
  #items = [];
  #maxSize;
  #consumers = [];
  #producers = [];

  constructor(maxSize) { this.#maxSize = maxSize; }

  async enqueue(item) {
    if (this.#items.length < this.#maxSize) {
      this.#items.push(item);
      this.#consumers.shift()?.(); // wake waiting consumer
    } else {
      // Queue full — producer blocks until consumer takes item
      await new Promise(r => this.#producers.push(r));
      this.#items.push(item);
    }
  }

  async dequeue() {
    if (this.#items.length > 0) {
      const item = this.#items.shift();
      this.#producers.shift()?.(); // wake waiting producer
      return item;
    }
    return new Promise(r => this.#consumers.push(
      () => r(this.#items.shift())
    ));
  }
}

const queue = new BoundedQueue(10); // max 10 items buffered

// Producer fills queue — pauses when full
const produce = async () => {
  for (const item of dataSource) await queue.enqueue(item);
};

// Consumer drains queue — producer unblocks as space opens
const consume = async () => {
  while (true) {
    const item = await queue.dequeue();
    await processSlowly(item);
  }
};

await Promise.all([produce(), consume()]);
```

