MutationObserver watches DOM changes asynchronously — callbacks are batched, never block rendering. Replaces deprecated synchronous mutation events.

Basic observation:
```javascript
const observer = new MutationObserver((mutations) => {
  for (const mutation of mutations) {
    if (mutation.type === 'childList') {
      mutation.addedNodes.forEach(node => console.log('Added:', node));
      mutation.removedNodes.forEach(node => console.log('Removed:', node));
    } else if (mutation.type === 'attributes') {
      console.log(`Attribute '${mutation.attributeName}' changed`);
      console.log('Old:', mutation.oldValue);
    }
  }
});

observer.observe(document.body, {
  childList: true,   // watch child additions/removals
  subtree: true,     // watch all descendants
  attributes: true,  // watch attribute changes
  attributeOldValue: true, // include old value in record
  characterData: true,     // watch text content changes
});
```

Async response to DOM changes:
```javascript
function waitForElement(selector, timeout = 5000) {
  return new Promise((resolve, reject) => {
    const existing = document.querySelector(selector);
    if (existing) return resolve(existing);

    const observer = new MutationObserver((mutations) => {
      const el = document.querySelector(selector);
      if (el) {
        observer.disconnect();
        resolve(el);
      }
    });

    observer.observe(document.body, { childList: true, subtree: true });
    setTimeout(() => {
      observer.disconnect();
      reject(new Error(`Element ${selector} not found within ${timeout}ms`));
    }, timeout);
  });
}

const dynamicEl = await waitForElement('#dynamic-content');
```

Batch processing mutations:
```javascript
const observer = new MutationObserver((mutations) => {
  // Mutations are batched — process all at once
  const addedNodes = mutations
    .filter(m => m.type === 'childList')
    .flatMap(m => [...m.addedNodes])
    .filter(n => n.nodeType === Node.ELEMENT_NODE);

  if (addedNodes.length) {
    initializeComponents(addedNodes); // async-safe batch init
  }
});

observer.disconnect(); // stop observing when done
const pending = observer.takeRecords(); // drain pending before disconnect
```

