Saga pattern manages long-running async transactions with compensating actions — if any step fails, execute rollback actions in reverse to undo completed steps.

```javascript
class Saga {
  #steps = [];
  #compensations = [];

  step(execute, compensate) {
    this.#steps.push({ execute, compensate });
    return this;
  }

  async run(ctx) {
    const completed = [];

    for (const { execute, compensate } of this.#steps) {
      try {
        await execute(ctx);
        completed.unshift(compensate); // prepend — LIFO for rollback
      } catch (err) {
        console.error('Step failed — rolling back:', err.message);
        // Execute all compensation actions in reverse
        for (const rollback of completed) {
          try {
            await rollback(ctx);
          } catch (rollbackErr) {
            console.error('Rollback failed:', rollbackErr.message);
          }
        }
        throw err; // re-throw original error
      }
    }
  }
}

// E-commerce order saga
const orderSaga = new Saga()
  .step(
    async (ctx) => { ctx.orderId = await createOrder(ctx.items); },
    async (ctx) => { await cancelOrder(ctx.orderId); }
  )
  .step(
    async (ctx) => { ctx.paymentId = await chargeCard(ctx.amount); },
    async (ctx) => { await refundPayment(ctx.paymentId); }
  )
  .step(
    async (ctx) => { ctx.shipmentId = await reserveInventory(ctx.items); },
    async (ctx) => { await releaseInventory(ctx.shipmentId); }
  )
  .step(
    async (ctx) => { await sendConfirmationEmail(ctx.orderId); },
    async (ctx) => { await sendCancellationEmail(ctx.orderId); }
  );

try {
  await orderSaga.run({ items: cart, amount: total });
  console.log('Order complete');
} catch (err) {
  console.log('Order failed — fully rolled back');
}
```

Use for: multi-service distributed operations, financial transactions, multi-step workflows where partial completion is unacceptable.

