**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Exponential backoff doubles wait time on each retry. Adding jitter (randomness) prevents thundering herd when many clients retry simultaneously after a service outage.

Basic exponential backoff:
```javascript
async function withBackoff(fn, { maxRetries = 5, baseMs = 100, maxMs = 30000 } = {}) {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt === maxRetries) throw err;
      if (err.name === 'AbortError') throw err; // never retry cancellation

      const delay = Math.min(baseMs * 2 ** attempt, maxMs);
      await new Promise(r => setTimeout(r, delay));
    }
  }
}

await withBackoff(() => fetch('/api/data').then(r => r.json()));
// Delays: 100ms, 200ms, 400ms, 800ms, 1600ms
```

With full jitter (prevents thundering herd):
```javascript
async function withJitteredBackoff(fn, { maxRetries = 5, baseMs = 100, maxMs = 30000 } = {}) {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt === maxRetries) throw err;
      if (err.name === 'AbortError') throw err;

      const cap = Math.min(maxMs, baseMs * 2 ** attempt);
      const delay = Math.random() * cap; // full jitter: random in [0, cap]
      await new Promise(r => setTimeout(r, delay));
    }
  }
}
// 100 clients retrying simultaneously: all get different delays — no thundering herd
```

With signal for cancellation:
```javascript
async function fetchRetry(url, signal, maxRetries = 3) {
  for (let i = 0; i <= maxRetries; i++) {
    try {
      const res = await fetch(url, { signal });
      if (res.ok) return res.json();
      if (res.status < 500) throw new Error(`HTTP ${res.status}`); // no retry for 4xx
    } catch (err) {
      if (err.name === 'AbortError' || i === maxRetries) throw err;
      const delay = Math.random() * Math.min(30000, 100 * 2 ** i);
      await new Promise(r => setTimeout(r, delay));
    }
  }
}
```

