**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Long polling repeatedly calls an endpoint waiting for new data. Without proper cleanup — cancellation on unmount/navigate, exponential backoff on error — it creates runaway request loops and memory leaks.

Bad — no cleanup, no backoff:
```javascript
async function startPolling(onData) {
  while (true) { // runs forever — no way to stop
    try {
      const data = await fetch('/api/events').then(r => r.json());
      onData(data);
    } catch (err) {
      console.error(err);
      // Error → immediate retry → hammers server if down!
    }
  }
}

startPolling(updateUI); // can never stop this
```

Good — cancellable with backoff:
```javascript
function startPolling(onData, onError) {
  const controller = new AbortController();
  let delay = 1000;

  async function poll() {
    while (!controller.signal.aborted) {
      try {
        const res = await fetch('/api/events', { signal: controller.signal });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        onData(data);
        delay = 1000; // reset backoff on success
      } catch (err) {
        if (err.name === 'AbortError') return; // cancelled — stop cleanly
        onError?.(err);
        // Exponential backoff on error
        delay = Math.min(delay * 2, 30000);
      }
      // Wait before next poll
      await new Promise(r => setTimeout(r, delay));
    }
  }

  poll();
  return () => controller.abort(); // return stop function
}

const stop = startPolling(updateUI, console.error);
// Component unmounts:
stop(); // cancels in-flight request and stops loop
```

Prefer WebSockets or SSE over polling when server supports it — they push data without polling overhead.

