A read-write lock allows multiple concurrent readers OR one exclusive writer. Better throughput than a simple mutex when reads dominate.

```javascript
class AsyncReadWriteLock {
  #readers = 0;
  #writing = false;
  #readWaiters = [];
  #writeWaiters = [];

  async acquireRead() {
    if (!this.#writing && this.#writeWaiters.length === 0) {
      this.#readers++;
      return;
    }
    await new Promise(r => this.#readWaiters.push(r));
    this.#readers++;
  }

  releaseRead() {
    this.#readers--;
    if (this.#readers === 0 && this.#writeWaiters.length) {
      const next = this.#writeWaiters.shift();
      this.#writing = true;
      next();
    }
  }

  async acquireWrite() {
    if (!this.#writing && this.#readers === 0) {
      this.#writing = true;
      return;
    }
    await new Promise(r => this.#writeWaiters.push(r));
  }

  releaseWrite() {
    this.#writing = false;
    if (this.#writeWaiters.length) {
      this.#writing = true;
      this.#writeWaiters.shift()();
    } else {
      const waiters = this.#readWaiters.splice(0);
      waiters.forEach(r => r()); // wake all readers
    }
  }

  async withRead(fn) {
    await this.acquireRead();
    try { return await fn(); }
    finally { this.releaseRead(); }
  }

  async withWrite(fn) {
    await this.acquireWrite();
    try { return await fn(); }
    finally { this.releaseWrite(); }
  }
}

const lock = new AsyncReadWriteLock();

// Multiple concurrent reads — all proceed simultaneously
await Promise.all([
  lock.withRead(() => fetchData()),
  lock.withRead(() => fetchData()),
  lock.withRead(() => fetchData()),
]);

// Write blocks until all reads complete — then exclusive
await lock.withWrite(() => updateData(newValue));
```

