fetch('/api/user')
  .then(response => {
    return response.json().then(user => {
      return fetchOrders(user.id).then(orders => {
        return Promise.all(orders.map(o => fetchOrderDetail(o.id))).then(details => {
          return processAll(user, details).then(result => {
            return saveResult(result).then(() => {
              displaySuccess(result);
            });
          });
        });
      });
    });
  })
  .catch(err => console.error(err)); // catches all — hard to know which step failed
```

Good — flat async/await:
```javascript
async function loadUserOrders() {
  try {
    const response = await fetch('/api/user');
    const user = await response.json();
    const orders = await fetchOrders(user.id);
    const details = await Promise.all(orders.map(o => fetchOrderDetail(o.id)));
    const result = await processAll(user, details);
    await saveResult(result);
    displaySuccess(result);
  } catch (err) {
    // Can add granular try/catch per step if needed
    console.error('Failed at some step:', err);
  }
}
```

Good — flat .then() chain (no nesting):
```javascript
fetch('/api/user')
  .then(r => r.json())
  .then(user => fetchOrders(user.id))
  .then(orders => Promise.all(orders.map(o => fetchOrderDetail(o.id))))
  .then(details => processAll(details))
  .then(result => saveResult(result))
  .then(displaySuccess)
  .catch(err => console.error('Failed:', err));
// Flat — each .then() is at same indentation level
```

