**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Promise.all preserves input order in results regardless of resolution order. Useful when processing items concurrently but needing results in original sequence.

Basic ordered concurrent map:
```javascript
async function concurrentMap(items, asyncFn) {
  return Promise.all(items.map(asyncFn));
  // Result[i] corresponds to items[i] — order preserved
}

const urls = ['/api/1', '/api/2', '/api/3'];
const data = await concurrentMap(urls, url => fetch(url).then(r => r.json()));
// data[0] is from /api/1, data[1] from /api/2, data[2] from /api/3
// even if /api/3 responds first
```

With error handling per item:
```javascript
async function concurrentMapSafe(items, asyncFn) {
  const results = await Promise.allSettled(items.map(asyncFn));
  return results.map((r, i) => ({
    index: i,
    input: items[i],
    ok: r.status === 'fulfilled',
    value: r.status === 'fulfilled' ? r.value : null,
    error: r.status === 'rejected' ? r.reason : null,
  }));
}

const results = await concurrentMapSafe(userIds, fetchUser);
const succeeded = results.filter(r => r.ok).map(r => r.value);
const failed = results.filter(r => !r.ok);
```

Bounded concurrent map (max N at a time, ordered results):
```javascript
async function boundedMap(items, asyncFn, concurrency) {
  const results = new Array(items.length);
  const executing = [];

  for (let i = 0; i < items.length; i++) {
    const idx = i; // capture for closure
    const p = asyncFn(items[idx]).then(result => {
      results[idx] = result; // store at original index
      executing.splice(executing.indexOf(p), 1);
    });
    executing.push(p);
    if (executing.length >= concurrency) await Promise.race(executing);
  }

  await Promise.all(executing);
  return results; // ordered by input, not completion order
}

