Async operations started during component mount that complete after unmount try to set state on unmounted components — causing memory leaks and 'setState on unmounted component' warnings.

Bug — sets state after unmount:
```javascript
// React class component
componentDidMount() {
  this.subscription = webSocket.subscribe((data) => {
    this.setState({ data }); // may run after unmount!
  });
}
// Missing componentWillUnmount cleanup — memory leak!
```

Fix — always cleanup in useEffect return:
```javascript
function LiveData({ channel }) {
  const [data, setData] = useState(null);

  useEffect(() => {
    const ws = new WebSocket(`wss://api.example.com/${channel}`);
    ws.onmessage = (e) => setData(JSON.parse(e.data));

    return () => ws.close(); // cleanup on unmount
  }, [channel]);

  return <div>{data}</div>;
}
```

Fix — AbortController for fetch:
```javascript
function UserProfile({ userId }) {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const ctrl = new AbortController();

    fetch(`/api/users/${userId}`, { signal: ctrl.signal })
      .then(r => r.json())
      .then(setUser)
      .catch(err => {
        if (err.name !== 'AbortError') console.error(err);
      });

    return () => ctrl.abort(); // cancel on unmount
  }, [userId]);
}
```

Fix — interval cleanup:
```javascript
function LiveClock() {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const interval = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(interval); // always clean up!
  }, []);

  return <div>{time.toLocaleTimeString()}</div>;
}
```

