**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Execute async tasks in dependency order — tasks with no dependencies run first (in parallel), then tasks whose dependencies are satisfied, and so on. Topological sort for async work.

```javascript
class AsyncTaskGraph {
  #tasks = new Map();

  add(name, deps, fn) {
    this.#tasks.set(name, { deps, fn });
    return this;
  }

  async run() {
    const results = new Map();
    const executing = new Map(); // name -> promise

    const runTask = (name) => {
      if (executing.has(name)) return executing.get(name);

      const { deps, fn } = this.#tasks.get(name);

      const promise = Promise.all(deps.map(dep => runTask(dep)))
        .then(depResults => {
          const depMap = Object.fromEntries(deps.map((d, i) => [d, depResults[i]]));
          return fn(depMap);
        })
        .then(result => {
          results.set(name, result);
          return result;
        });

      executing.set(name, promise);
      return promise;
    };

    await Promise.all([...this.#tasks.keys()].map(runTask));
    return results;
  }
}

// Build pipeline: fetch → parse → transform → save (with parallelism)
const graph = new AsyncTaskGraph()
  .add('fetchUsers', [], () => fetch('/api/users').then(r => r.json()))
  .add('fetchRoles', [], () => fetch('/api/roles').then(r => r.json()))
  .add('merge', ['fetchUsers', 'fetchRoles'], ({ fetchUsers, fetchRoles }) =>
