SharedWorker instances are shared across same-origin tabs. Multiple tabs writing to shared worker state concurrently without coordination creates race conditions.

Bug — concurrent state modification via SharedWorker:
```javascript
// shared-worker.js
let sharedCounter = 0;

self.onconnect = (e) => {
  const port = e.ports[0];
  port.onmessage = (msg) => {
    if (msg.data.type === 'increment') {
      sharedCounter++; // safe — single-threaded worker
      port.postMessage({ counter: sharedCounter });
    }
  };
};
// Counter is safe inside SharedWorker (single thread)
// But coordination across ports needs serialization
```

Bug — concurrent async operations in SharedWorker:
```javascript
self.onconnect = (e) => {
  const port = e.ports[0];
  port.onmessage = async (msg) => {
    const current = sharedData.value; // read
    await fetchUpdate(); // yield — another port's message can run here!
    sharedData.value = current + 1; // write — lost update!
  };
};
```

Fix — queue all messages through serial processor:
```javascript
// shared-worker.js
let sharedState = {};
const ports = new Set();
let processing = Promise.resolve();

function broadcast(data) {
  ports.forEach(p => p.postMessage(data));
}

self.onconnect = (e) => {
  const port = e.ports[0];
  ports.add(port);

  port.onmessage = (msg) => {
    // Serialize all state mutations through a queue
    processing = processing.then(async () => {
      const result = await handleMessage(msg.data, sharedState);
      sharedState = result.newState;
      broadcast(sharedState); // all tabs get updated state
    }).catch(err => console.error('Worker error:', err));
  };

  port.onclose = () => ports.delete(port);
};
```

