**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Resource lifecycle hooks (onCreate, onAcquire, onRelease, onDestroy) enable instrumentation, monitoring, and policy enforcement without modifying resource logic.

```javascript
class InstrumentedPool {
  #resources = [];
  #available = [];
  #hooks;
  #maxSize;

  constructor(factory, maxSize = 10, hooks = {}) {
    this.#factory = factory;
    this.#maxSize = maxSize;
    this.#hooks = {
      onCreate: hooks.onCreate ?? (() => {}),
      onAcquire: hooks.onAcquire ?? (() => {}),
      onRelease: hooks.onRelease ?? (() => {}),
      onDestroy: hooks.onDestroy ?? (() => {}),
    };
  }

  async acquire() {
    let resource;
    if (this.#available.length) {
      resource = this.#available.pop();
    } else if (this.#resources.length < this.#maxSize) {
      resource = await this.#factory();
      this.#resources.push(resource);
      await this.#hooks.onCreate(resource);
    } else {
      throw new Error('Pool exhausted');
    }
    await this.#hooks.onAcquire(resource);
    return resource;
  }

  async release(resource) {
    await this.#hooks.onRelease(resource);
    this.#available.push(resource);
  }

  async with(fn) {
    const resource = await this.acquire();
    try { return await fn(resource); }
    finally { await this.release(resource); }
  }
}

// Pool with full observability:
const dbPool = new InstrumentedPool(
  createConnection,
  5,
  {
    onCreate: (conn) => metrics.increment('pool.created'),
    onAcquire: (conn) => {
      conn._acquiredAt = Date.now();
      metrics.gauge('pool.active', 1);
    },
    onRelease: (conn) => {
      const held = Date.now() - conn._acquiredAt;
      metrics.histogram('pool.holdTime', held);
      metrics.gauge('pool.active', -1);
    },
  }
);

await dbPool.with(conn => conn.query('SELECT 1'));
```

