Event sourcing stores state changes as immutable events. Projections rebuild state by replaying events asynchronously — enables multiple views of the same data.

```javascript
class EventStore {
  #events = [];
  #subscribers = [];

  async append(event) {
    const entry = {
      id: crypto.randomUUID(),
      type: event.type,
      payload: event.payload,
      timestamp: Date.now(),
    };
    this.#events.push(entry);
    // Notify all projections
    await Promise.all(this.#subscribers.map(sub => sub(entry)));
    return entry;
  }

  subscribe(handler) {
    this.#subscribers.push(handler);
    return () => this.#subscribers.splice(this.#subscribers.indexOf(handler), 1);
  }

  async replay(fromId = null, handler) {
    const start = fromId
      ? this.#events.findIndex(e => e.id === fromId) + 1
      : 0;
    for (const event of this.#events.slice(start)) {
      await handler(event);
    }
  }
}

