When session token validation is async (DB lookup, JWT decode), concurrent requests may proceed past validation while a logout/revoke is processed.

Bug — revoke races with validation:
```javascript
const activeSessions = new Set();

async function validateSession(token) {
  // Step 1: check in-memory set (fast)
  if (!activeSessions.has(token)) return false;

  // Step 2: verify signature (slow)
  const payload = await verifyJWT(token); // yield here!
  // While awaiting, logout() may have removed token from activeSessions
  // But this validation still returns true — token accepted after revoke!

  return payload;
}

async function logout(token) {
  activeSessions.delete(token); // runs while validateSession is awaiting verifyJWT
}
```

Fix — re-check after async operation:
```javascript
async function validateSession(token) {
  if (!activeSessions.has(token)) return false;

  const payload = await verifyJWT(token);

  // Re-check after await — token may have been revoked during verification
  if (!activeSessions.has(token)) return false;

  return payload;
}
```

Fix — version-based session invalidation:
```javascript
const sessions = new Map(); // token -> { version, userId }

async function validateSession(token) {
  const session = sessions.get(token);
  if (!session) return false;
  const snapshotVersion = session.version;

  const payload = await verifyJWT(token);

  const current = sessions.get(token);
  if (!current || current.version !== snapshotVersion) return false; // revoked
  return payload;
}

async function logout(token) {
  sessions.delete(token); // or: sessions.get(token).version++ to invalidate
}
```

Fix — centralized auth service with read-your-writes:
```javascript
async function validateSession(token) {
  // Single authoritative check — no split state
  return authService.validate(token); // handles revocation internally
}
```

