  // Modify THEN yield — no shared state read after yield point
  if (sharedBalance < amount) {
    yield { ok: false, reason: 'Insufficient funds' };
    return;
  }
  sharedBalance -= amount; // atomic — no yield between read and write
  yield { ok: true, balance: sharedBalance };
}
