**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Long-running async workflows can be interrupted (network failure, process restart). Checkpointing saves progress at each stage so the workflow can resume from last checkpoint instead of restarting.

```javascript
class CheckpointedWorkflow {
  #checkpoints;
  #workflowId;

  constructor(workflowId, persistFn, loadFn) {
    this.#workflowId = workflowId;
    this.persist = persistFn;
    this.load = loadFn;
  }

  async run(stages) {
    // Load existing checkpoint
    const saved = await this.load(this.#workflowId) ?? { stage: 0, data: {} };
    let { stage: startStage, data: ctx } = saved;

    console.log(`Resuming workflow from stage ${startStage}/${stages.length}`);

    for (let i = startStage; i < stages.length; i++) {
      const { name, fn } = stages[i];
      try {
        console.log(`Running stage ${i}: ${name}`);
        ctx = { ...ctx, ...(await fn(ctx)) };

        // Save checkpoint after each successful stage
        await this.persist(this.#workflowId, { stage: i + 1, data: ctx });
        console.log(`Stage ${name} complete — checkpoint saved`);
      } catch (err) {
        console.error(`Stage ${name} failed:`, err);
        throw err; // will resume from this stage on next run
      }
    }

    await this.persist(this.#workflowId, null); // clear checkpoint
    return ctx;
  }
}

// Data migration workflow:
const migration = new CheckpointedWorkflow(
  'migration-2024-01',
  (id, data) => db.save('checkpoints', id, data),
  (id) => db.load('checkpoints', id)
);

const result = await migration.run([
  { name: 'export',    fn: (ctx) => exportOldData().then(data => ({ data })) },
  { name: 'transform', fn: (ctx) => transformData(ctx.data).then(rows => ({ rows })) },
  { name: 'validate',  fn: (ctx) => validateRows(ctx.rows).then(valid => ({ valid })) },
  { name: 'import',    fn: (ctx) => importData(ctx.valid).then(count => ({ count })) },
]);
```

