**Scenario (E-commerce):** Implementing this pattern to handle products efficiently.

Throttle limits how often a function runs. Debounce delays execution until after a quiet period. Both prevent concurrent async operation overload.

Debounce — wait for pause before executing:
```javascript
function debounce(fn, delay) {
  let timer = null;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

// Search only after user stops typing for 300ms
const debouncedSearch = debounce(async (query) => {
  const results = await fetch(`/api/search?q=${query}`).then(r => r.json());
  renderResults(results);
}, 300);

inputEl.addEventListener('input', (e) => debouncedSearch(e.target.value));
```

Throttle — execute at most once per interval:
```javascript
function throttle(fn, interval) {
  let lastCall = 0;
  return function(...args) {
    const now = Date.now();
    if (now - lastCall >= interval) {
      lastCall = now;
      return fn.apply(this, args);
    }
  };
}

// Save at most once per second even if called frequently
const throttledSave = throttle(async () => {
  await saveDocument(currentContent);
}, 1000);

document.addEventListener('keyup', throttledSave);
```

Async-aware debounce (returns promise):
```javascript
function asyncDebounce(fn, delay) {
  let timer = null;
  let pendingResolve = null;

  return function(...args) {
    clearTimeout(timer);
    return new Promise((resolve) => {
      pendingResolve = resolve;
      timer = setTimeout(async () => {
        const result = await fn.apply(this, args);
        pendingResolve(result);
      }, delay);
    });
  };
}
```

